/* Offene Fragen (2 Punkte je Frage, Selbstbewertung).
   Format:
     { t: Thema,
       q: Frage,
       a: [Musterlösung als Stichpunkte],
       r: { d: Kürzel aus RS.DOCS, s: Abschnitt, p: "S. 4" bzw. "S. 4–5" } }
   Die Seitenzahl für den PDF-Direktlink wird aus `p` gelesen (erste Zahl).
   Die Frage-ID wird beim Laden aus dem Fragetext gebildet – Fragen dürfen
   also frei umsortiert werden, ohne dass der Lernfortschritt verloren geht. */
window.RS = window.RS || {};
RS.OPEN = [
/* ===== Respiratorische Notfälle ===== */
{t:"Respiratorische Notfälle", q:"Definieren Sie den Begriff Dyspnoe und nennen Sie jeweils drei Ursachen innerhalb und außerhalb des Atmungssystems.",
 a:["Dyspnoe = subjektives Gefühl erschwerter Atmung, meist mit erhöhter Atemfrequenz (Tachypnoe) als Kompensationsversuch bei unzureichender O2-Versorgung","Innerhalb des Atmungssystems: obere Atemwege (Schleimhautschwellung, Fremdkörper, Verletzung), untere Atemwege (Asthma, COPD, Fremdkörper), Lunge (Pneumonie, Lungenödem), Pleura (Pneumothorax, Pleuraerguss), Lungengefäße (Lungenembolie)","Außerhalb: kardial (Herzinsuffizienz), psychogen (Hyperventilation), zerebral (Atemzentrum, Trauma, Intoxikation), Stoffwechsel (entgleister Diabetes), Anämie"],
 r:{d:"N", s:"Respiratorische Notfälle – Atemnot (Dyspnoe)", p:"S. 1"}},
{t:"Respiratorische Notfälle", q:"Welche Hinweise aus der Anamnese sprechen bei Atemnot für eine Lungenembolie, welche für eine Hyperventilation?",
 a:["Lungenembolie: plötzlicher Beginn, gestaute Halsvenen, Thoraxschmerzen, Husten; Risikofaktoren: längere Reise, größere OP, Bettlägerigkeit","Hyperventilation: Tachypnoe, Tachykardie, Kribbeln, Pfötchenstellung; Auslöser meist psychische Belastung"],
 r:{d:"N", s:"Dyspnoe – Anamnese", p:"S. 1–2"}},
{t:"Respiratorische Notfälle", q:"Erklären Sie den Unterschied zwischen zentraler und peripherer Zyanose (Entstehung und Erkennungsmerkmal).",
 a:["Zentrale Zyanose: O2-Sättigung bereits im arteriellen Blut zu gering (z.B. Herzfehler mit Rechts-Links-Shunt, Lungenembolie, COPD, Asthma, Linksherzinsuffizienz) → Zunge und Mundschleimhaut blau","Periphere Zyanose: erhöhte O2-Ausschöpfung in den Kapillaren (z.B. Herzinsuffizienz, venöse Thrombose) → Lippen, Hände, Füße blau"],
 r:{d:"N", s:"Zyanose", p:"S. 2"}},
{t:"Respiratorische Notfälle", q:"Nennen Sie fünf Zeichen akuter Lebensgefahr bei einem respiratorischen Notfall.",
 a:["Schnappatmung / Atemstillstand","Verschlechterung der Atemnot im Verlauf, muskuläre Erschöpfung","pathologische Atemmuster, paradoxe oder inverse Atmung","akut aufgetretene Zyanose","Bewusstseinsstörung / Bewusstlosigkeit","Kreislaufinstabilität, Schockzeichen"],
 r:{d:"N", s:"Anamnese und Untersuchung – Akute Lebensgefahr", p:"S. 3"}},
{t:"Respiratorische Notfälle", q:"Welche Basismaßnahmen führen Sie bei einem Patienten mit Atemnot durch? Nennen Sie auch die Zielwerte der Sauerstoffsättigung.",
 a:["Basismaßnahmen nach xABCDE, insbesondere Auskultation und EKG","atemerleichternde Lagerung (Oberkörper aufrecht)","Patient beruhigen, Wärmeerhalt","frühzeitige O2-Gabe über Maske: Ziel SpO2 92–96 %, bei COPD 88–92 %","je nach Kreislauf i.v.-Zugang vorbereiten, ggf. Intubation und Absaugung bereithalten"],
 r:{d:"N", s:"Respiratorische Notfälle – Maßnahmen", p:"S. 3"}},
{t:"Respiratorische Notfälle", q:"Was passiert beim Asthma bronchiale in den Bronchien und welche Auslöser (allergisch und nicht allergisch) kennen Sie?",
 a:["Bronchialsystem ist überempfindlich → chronische Entzündung mit anfallsweiser Verengung","Mechanismus: vermehrte Sekret-/Schleimproduktion, Schleimhautschwellung, Spasmen der Bronchialmuskulatur → Verengung, Problem vor allem bei der Ausatmung","Allergisch/extrinsisch: Tierhaare, Hausstaub, Pollen","Nicht allergisch/intrinsisch: Rauch, kalte Luft, Atemwegsinfekte, Medikamente (ASS, NSAR), psychische Belastung, Schmerz, körperliche Belastung (Anstrengungsasthma)"],
 r:{d:"N", s:"Asthma bronchiale – Ursachen", p:"S. 3"}},
{t:"Respiratorische Notfälle", q:"Nennen Sie typische Symptome eines Asthmaanfalls und beschreiben Sie, woran Sie einen lebensbedrohlichen Verlauf erkennen.",
 a:["Typisch: plötzliche Atemnot, Sprechprobleme, Einsatz der Atemhilfsmuskulatur, atemerleichternde Haltung, Unruhe/Panik, trockener Husten, Schweiß, erhöhte HF und AF, verlängerte Ausatmung mit exspiratorischem Giemen/Brummen, ggf. Zyanose","Bedrohlich: Ausfall der Sprache, SpO2 fällt stark, Verwirrtheit/Schläfrigkeit, Zyanose, „stille Lunge“ (keine Atemgeräusche), flache langsame unregelmäßige Atmung, sinkende Herzfrequenz","Komplikation: muskuläre Erschöpfung mit Hyperkapnie und Hypoxämie"],
 r:{d:"N", s:"Asthma bronchiale – Symptomatik", p:"S. 3–4"}},
{t:"Respiratorische Notfälle", q:"Welche Maßnahmen ergreifen Sie beim Asthmaanfall? Worauf ist beim Einsatz des patienteneigenen Asthmasprays zu achten?",
 a:["Aufrechte Lagerung, atemerleichternde Haltung (Kutschersitz, Torwarthaltung)","xABCDE, Basismonitoring, zügige O2-Gabe","enge Kleidung öffnen, Frischluft, beruhigen und betreuen","Lippenbremse, Atemkommandos","eigenes Asthmaspray anleiten/verabreichen: erweitert die Bronchien, triggert den Sympathikus → auf Häufigkeit der Anwendung und Herzfrequenz achten","Notarzt bei fehlender Besserung, schwerer Dyspnoe, vitaler Bedrohung; i.v.-Zugang vorbereiten; Intubation/Beatmung als Ultima Ratio"],
 r:{d:"N", s:"Asthma bronchiale – Anamnese und Maßnahmen", p:"S. 4"}},
{t:"Respiratorische Notfälle", q:"Definieren Sie COPD, nennen Sie die AHA-Symptome und drei Risikofaktoren.",
 a:["COPD = chronisch-obstruktive Lungenerkrankung mit zunehmender, unumkehrbarer Verengung der Bronchien","Entwicklung: Schadstoffe schädigen die Bronchialschleimhaut → chronische Bronchitis → irreversible Gewebeveränderung; bei Zerstörung der Alveolen Lungenemphysem","AHA: Auswurf, Husten, Atemnot (erst unter Belastung, später auch in Ruhe)","Risikofaktoren: Zigarettenrauch, Luftschadstoffe, Genetik, häufige virale Atemwegsinfekte in der Kindheit, gestörte vorgeburtliche Lungenentwicklung"],
 r:{d:"N", s:"COPD – Definition, Ursachen, Symptomatik", p:"S. 4–5"}},
{t:"Respiratorische Notfälle", q:"Wie dosieren Sie Sauerstoff bei einem COPD-Patienten und warum wird hier „kontrolliert“ gegeben?",
 a:["Zielbereich SpO2 88–92 %","bei SpO2 > 80 %: ca. 3 l/min über Nasenbrille; bei < 80 %: 6–10 l/min über Maske","Grund: COPD-Patienten haben eine chronische Hypoxämie und eine respiratorische Globalinsuffizienz – deshalb kontrolliert bis 88–92 % statt so viel wie möglich","Warnzeichen bei AECOPD: plötzlich fallende Herzfrequenz, Bewusstseinsstörung"],
 r:{d:"N", s:"COPD – Anamnese und Maßnahmen", p:"S. 5"}},
{t:"Respiratorische Notfälle", q:"Erklären Sie, wie es bei COPD zum Cor pulmonale kommt.",
 a:["Chronische Hypoxie durch behinderte Ventilation der Alveolen","Verengung der Lungenarterien → Druckerhöhung im Lungenkreislauf (pulmonale Hypertonie)","Das rechte Herz muss gegen diesen Druck pumpen und wird chronisch überlastet → Rechtsherzinsuffizienz (Cor pulmonale)","Zeichen: Unterschenkelödeme, gestaute Halsvenen, nachlassende Herzleistung"],
 r:{d:"N", s:"COPD – Komplikationen", p:"S. 5"}},
{t:"Respiratorische Notfälle", q:"Beschreiben Sie die Symptome einer Pneumonie (typisch und atypisch) und die Besonderheit bei älteren Patienten. Welche Maßnahmen führen Sie durch?",
 a:["Typisch: plötzlich hohes Fieber, produktiver Husten, schweres Krankheitsgefühl, Rasselgeräusche","Atypisch: schleichend mit leichtem Fieber, trockener Reizhusten, mäßiges Krankheitsgefühl","Ältere: ggf. nur akute Verwirrtheit oder Bewusstseinsstörung","Komplikationen: atemabhängige Schmerzen/Pleuraerguss, Thrombose/Lungenembolie durch Bettruhe, septischer Schock, respiratorische Insuffizienz","Maßnahmen: aufrechte Lagerung, xABCDE + Monitoring inkl. Temperatur, O2 initial 10 l/min (Ziel 92–96 %), i.v.-Zugang/VEL vorbereiten, Notarzt je nach Bewusstseinslage"],
 r:{d:"N", s:"Lungenentzündung (Pneumonie)", p:"S. 5–6"}},
{t:"Respiratorische Notfälle", q:"Wie entsteht ein kardiales Lungenödem und welche Symptome zeigen den Verlauf bis zur Lebensgefahr an?",
 a:["Linksherzinsuffizienz → Blut staut sich in den Lungenkreislauf zurück → Druck in den Lungenkapillaren steigt → Flüssigkeit wird ins Interstitium und in die Alveolen gepresst","Folge: eingeschränkte Dehnbarkeit, verlängerte Diffusionsstrecke → Hypoxämie","Beginn: Unruhe, Husten, beginnende Atemnot, erhöhte Atemfrequenz","Fortschreitend: zunehmende Atemnot, kaltschweißige blasse/zyanotische Haut","Fortgeschritten: rosa Schaum aus dem Mund, Rasselgeräusche → Lebensgefahr"],
 r:{d:"N", s:"Lungenödem – Kardiales Lungenödem", p:"S. 6"}},
{t:"Respiratorische Notfälle", q:"Wie grenzen Sie ein kardiales Lungenödem von einem Asthmaanfall ab und welche Maßnahmen sind beim Lungenödem indiziert?",
 a:["Lungenödem: feuchte Rasselgeräusche bei Ein- UND Ausatmung, Haut feucht, Blutdruck hoch","Asthma: trockene Geräusche (Giemen) bei der Ausatmung, Haut trocken, Blutdruck normal","Maßnahmen: Standard + Herzbettlagerung (Oberkörper hoch, Beine tief), frühzeitig O2 initial 10 l/min, Absaugbereitschaft wegen Schaum, Notarzt"],
 r:{d:"N", s:"Kardiales Lungenödem – Differenzialdiagnose, Maßnahmen", p:"S. 6"}},
{t:"Respiratorische Notfälle", q:"Was ist ein toxisches Lungenödem, welche Latenzzeit ist zu beachten und welche Maßnahmen ergreifen Sie?",
 a:["Reiz-/Rauchgase erhöhen die Kapillardurchlässigkeit → Flüssigkeitsaustritt ins Interstitium und in die Alveolen (z.B. Chlorgas, Ammoniak, Nitrosegase, Brände)","Kann sich bis zu 36 Stunden nach Exposition entwickeln","Symptome: Atemnot, Husten, Würgereiz, Schwindel, Augenbrennen, Schleimhautreizung, inspiratorischer Stridor, feuchte RG, Bewusstseinsstörung; bei Rauchgas rußiges Sekret, Verbrennungen, ggf. CO-Vergiftung","Maßnahmen: 1. Rettung aus dem Gefahrenbereich + Eigenschutz, 2. xABCDE + Monitoring mit Atemwegsinspektion, 3. großzügig O2 (10–15 l/min), 4. Augen/Mund/Haut spülen, 5. verrauchte Kleidung entfernen, Wärmeerhalt"],
 r:{d:"N", s:"Lungenödem – Toxisches Lungenödem", p:"S. 6–7"}},
{t:"Respiratorische Notfälle", q:"Erklären Sie die Pathophysiologie der Hyperventilation, ihre Symptome und Ihre Maßnahmen. Welche Differenzialdiagnosen müssen ausgeschlossen werden?",
 a:["Unbewusst schnellere und tiefere Atmung → vermehrt CO2 abgeatmet → Hypokapnie → pH-Wert steigt → freies Kalzium sinkt (Hypokalzämie)","Symptome: Erstickungsgefühl, Pfötchenstellung, Gefühlsstörungen, Schwindel, pelziges Gefühl im Mund, ggf. Muskelkrämpfe; keine Lebensgefahr","Ursache: emotionale Belastung, Angst-/Panikattacke","Maßnahmen: vor Verletzungen schützen, beruhigen und über Harmlosigkeit aufklären, aufrechte Lagerung, SAMPLER, Atmung anleiten oder Rückatmung mit Plastiktüte, Notarzt nach 10–15 min ohne Besserung (Beruhigungsmittel)","DD: metabolische Azidose, Lungenembolie (Hyperventilation kann Symptom sein)"],
 r:{d:"N", s:"Hyperventilation", p:"S. 7"}},
{t:"Respiratorische Notfälle", q:"Beschreiben Sie die Pathophysiologie beim Ertrinken und nennen Sie die wichtigsten Maßnahmen inklusive der Besonderheit bei der Reanimation.",
 a:["Untertauchen → Unterbrechung der O2-Zufuhr, Aspiration von Wasser → reflektorischer Stimmritzenkrampf (Laryngospasmus)","Zunehmende Hypoxie → Bewusstlosigkeit → Krampf löst sich → Wasser dringt in die unteren Atemwege, Alveolen kollabieren","Maßnahmen: Wasserrettung durch Spezialkräfte (Feuerwehr, DLRG), Eigenschutz; Notarzt; frühzeitig O2 + Absaugbereitschaft; xABCDE + Monitoring; Lagerung nach Bewusstsein; Atemwege sichern, assistierte/kontrollierte Beatmung; Kleidung entfernen, abtrocknen, Wärmeerhalt; Begleitverletzungen suchen","Reanimation mit 5 initialen Beatmungen; Reanimation bis zur Erwärmung des Patienten fortführen"],
 r:{d:"N", s:"Ertrinkungsunfälle", p:"S. 8"}},
{t:"Respiratorische Notfälle", q:"Ein Patient hat einen Fremdkörper aspiriert. Beschreiben Sie Ihr Vorgehen bei (a) sichtbarem Fremdkörper, (b) nicht sichtbarem Fremdkörper bei Bewusstsein, (c) Bewusstlosigkeit und (d) bei Kindern.",
 a:["Allgemein: Oberkörper hochlagern; Notarzt nach erstem erfolglosen Entfernungsversuch","(a) sichtbar: manuell ausräumen oder mit Magillzange entfernen","(b) bei Bewusstsein: zum Husten auffordern → Oberkörper nach vorn beugen, 5 Schläge mit der flachen Hand auf den Rücken → Heimlich-Handgriff","(c) bewusstlos: Reanimation","(d) Kinder: bei Dyspnoe/Zyanose Bauchlage, 5 Schläge zwischen die Schulterblätter; Säuglinge < 1 Jahr: statt Heimlich 5 Thoraxkompressionen","Flüssigkeiten: Kopf zur Seite, Ausräumen/Absaugen in Seitenlage"],
 r:{d:"N", s:"Aspiration – Anamnese und Maßnahmen", p:"S. 8–9"}},
{t:"Respiratorische Notfälle", q:"Nennen Sie Risikogruppen für eine Aspiration und drei Differenzialdiagnosen.",
 a:["Risikogruppen: Kleinkinder, ältere und verwirrte Menschen, Alkoholisierte, Patienten mit Schluckstörungen","DD: akute obstruktive Bronchitis (produktiver Husten, RG), Asthmaanfall, Epiglottitis (Fieber, inspiratorischer Stridor, Schluckstörung), Pseudokrupp (bellender Husten, inspiratorischer Stridor), allergische Reaktion"],
 r:{d:"N", s:"Aspiration – Risikogruppe, Differentialdiagnose", p:"S. 8–9"}},
{t:"Respiratorische Notfälle", q:"Worin unterscheiden sich Kohlendioxid (CO2) und Kohlenmonoxid (CO) hinsichtlich Eigenschaften, Wirkung im Körper und typischen Gefahrenquellen?",
 a:["CO2: ungiftig, geruch- und farblos, schwerer als Luft → sammelt sich am Boden und verdrängt O2; CO2 kann nicht mehr abgeatmet werden → Hyperkapnie + Hypoxie; Quellen: Futtersilos, Jauchegruben, Biogasanlagen, Weinkeller, Trockeneis, Brände","CO: farb-, geruch-, geschmacklos, giftig; bindet an Hämoglobin und blockiert die O2-Bindungsstellen; Quellen: unvollständige Verbrennung in geschlossenen Räumen (Wohnungs-/Kaminbrand, Kohlegrill, Motoren, Shisha-Bars, defekte Gasheizungen, Heizpilze)","Maßnahmen bei beiden: Spezialkräfte, Eigenschutz, xABCDE, O2 10–15 l/min bzw. hochdosiert, Notarzt; bei CO ggf. Druckkammer"],
 r:{d:"N", s:"Kohlendioxid-Erstickung / Kohlenmonoxid-Intoxikation", p:"S. 9–10"}},
{t:"Respiratorische Notfälle", q:"Nennen Sie Symptome einer CO-Intoxikation.",
 a:["Kopfschmerz, Schwindel, Benommenheit, Herzklopfen, Ohrensausen","Sehstörungen, Übelkeit, Erbrechen, Kollapsneigung","Anstieg von Herz- und Atemfrequenz","Vigilanzstörungen bis Bewusstlosigkeit, Herzrhythmusstörungen, Angina-pectoris-Symptomatik, Krampfanfälle","hypoxisch bedingter Herz-Kreislauf-Stillstand"],
 r:{d:"N", s:"Kohlenmonooxid-Intoxikation – Symptomatik", p:"S. 10"}},
{t:"Respiratorische Notfälle", q:"Definieren Sie Bronchiolitis, akute Epiglottitis und Pseudokrupp.",
 a:["Bronchiolitis: Entzündung und kritische Verengung der Bronchiolen durch virale Infektion","Akute Epiglottitis: Schleimhautschwellung mit Erstickungsgefahr durch akute bakterielle Entzündung des Kehldeckels (Fieber, inspiratorischer Stridor, Schluckstörung)","Pseudokrupp: Verengung der Atemwege durch Entzündung mit Anschwellen der Schleimhaut unterhalb der Stimmritze (bellender Husten, inspiratorischer Stridor)"],
 r:{d:"N", s:"Respiratorische Notfälle bei Kindern", p:"S. 10"}},

/* ===== Herz-Kreislauf & Schock ===== */
{t:"Herz-Kreislauf & Schock", q:"Definieren Sie Schock und erklären Sie die Bedeutung der Kreislaufzentralisation.",
 a:["Schock = Kreislaufversagen, das unbehandelt zum Multiorganversagen führen kann","Störung der Mikrozirkulation → O2-Minderversorgung des Gewebes","Kreislaufzentralisierung: der Körper versucht damit zunächst, die Versorgung der wichtigsten Organe sicherzustellen"],
 r:{d:"N", s:"Schock", p:"S. 10"}},
{t:"Herz-Kreislauf & Schock", q:"Nennen Sie die vier Schockformen mit jeweils mindestens einer Ursache.",
 a:["Volumenmangel-/hypovolämischer Schock: starke Blutung, Verbrennung, starker Durchfall/Erbrechen","Kardialer Schock: kardiogen (Herzinfarkt, Herzinsuffizienz) oder obstruktiv (Herzbeuteltamponade, Spannungspneumothorax)","Distributiver Schock (Verteilungsschock durch Vasodilatation + erhöhte Gefäßdurchlässigkeit): anaphylaktisch (Insektenstich, Nahrungsmittel), septisch (schwere Infektion), neurogen/spinal (SHT, Wirbelsäulentrauma)","„Psychischer Schock“ ist umgangssprachlich für die akute Belastungsreaktion, kein Schock im medizinischen Sinn"],
 r:{d:"N", s:"Schock – Arten", p:"S. 10–11"}},
{t:"Herz-Kreislauf & Schock", q:"Ab welchem Blutverlust wird es kritisch und welche Zeichen zeigt der Patient? Welche Lagerung ist indiziert und warum?",
 a:["Problematisch ab Blutverlust > 30 % des Blutvolumens","Herzfrequenz steigt, Blutdruck fällt → Patient blass, unruhig, kaltschweißig, ggf. Bewusstlosigkeit (hypovolämischer Schock)","Schocklagerung: Beine hochlagern → erhöht den venösen Rückstrom zum Herzen"],
 r:{d:"K", s:"Blut und Blutgefäße – Volumen / Schocklagerung", p:"S. 1 und 3"}},
{t:"Herz-Kreislauf & Schock", q:"Welche Begleitsymptome bei Thoraxschmerz sprechen für ein akutes Koronarsyndrom, und wohin strahlen kardiale Schmerzen typischerweise aus?",
 a:["Weitere Symptome beim ACS: Atemnot, Übelkeit, Schwindel, Blässe, Schweißausbruch","Aus der Anamnese bei Atemnot: Thoraxschmerzen mit Übelkeit, Erbrechen und Todesangst sprechen für ein akutes Koronarsyndrom","Leitsymptom: plötzlich auftretende Brustschmerzen mit Ausstrahlung in Unterkiefer, Arm und Schulter; Todesangst","Beim ACS retrosternaler Schmerz – bei Männern mit Ausstrahlung in den linken Oberarm, Schulter und Rücken, bei Frauen in Nacken, Hals, Kiefer, Rücken und Bauch"],
 r:{d:"N", s:"Akute Thoraxschmerzen – Anamnese / Dyspnoe – Anamnese", p:"S. 11–12 und 1"}},
{t:"Herz-Kreislauf & Schock", q:"Was passiert beim Herzinfarkt und warum ist Zeit so entscheidend?",
 a:["Eine Herzkranzarterie (Koronararterie) ist vollständig verschlossen → O2-Versorgung des betroffenen Gebiets unterbrochen","Herzmuskelzellen sterben innerhalb weniger Minuten ab (Myokardinfarkt)","Das Herz wird über die Koronararterien versorgt, nicht über das Blut im Innenraum","Notarztindikation: Verdacht auf Herzinfarkt"],
 r:{d:"K", s:"Herz-Kreislauf-System – Aufbau des Herzens", p:"S. 4"}},
{t:"Herz-Kreislauf & Schock", q:"Welche Maßnahmen ergreifen Sie je nach Schockform (hypovolämisch, anaphylaktisch, kardiogen, obstruktiv, neurogen)?",
 a:["Hypovolämisch: Blutstillung (äußere Blutungen mit Druckverband oder Tourniquet, innere Blutungen mit Beckenschlinge), Schocklagerung, Sauerstoffgabe, ggf. Immobilisation","Anaphylaktisch: Adrenalin, Sauerstoffgabe, Schocklagerung oder atemerleichternde Lagerung, beschleunigte Infusionstherapie, medikamentöse Therapie","Kardiogen: Oberkörperhochlagerung, Sauerstoffgabe, Monitoring und Differenzialdiagnostik, medikamentöse Therapie","Obstruktiv: Auslöser ermitteln, Lagerung optimieren, ggf. Sauerstoffgabe","Neurogen: abhängig von der Ursache, ggf. Immobilisierung, Sauerstoffgabe, Wärmeerhalt"],
 r:{d:"N", s:"Schock – Maßnahmen", p:"S. 11"}},
{t:"Herz-Kreislauf & Schock", q:"Wie erheben Sie die Anamnese bei akuten Thoraxschmerzen? Nennen Sie die Fragen nach dem OPQRST-Schema und die Ursachen, auf die die Antworten hinweisen.",
 a:["SAMPLER, insbesondere Vorerkrankungen und Medikamente, dazu OPQRST","Beginn: bei körperlicher Belastung oder psychischem Stress – Angina pectoris; in Ruhe – ACS; nach längerem Liegen oder Aufstehen – Lungenembolie","Entwicklung: Zunahme über Minuten – ACS; sofort maximale Stärke – Lungenembolie, Aortendissektion","Art: brennend, Engegefühl – Angina pectoris; Vernichtungsschmerz – Aortendissektion, ACS; reißend – Aortendissektion","Zunahme beim Atmen: atemabhängig – Lungenembolie, Pleuritis, Rippenfraktur; atemunabhängig – ACS, Angina pectoris","Ausstrahlung: retrosternaler Schmerz mit Ausstrahlung in linken Oberarm, Schulter, Rücken (Männer) bzw. Nacken, Hals, Kiefer, Rücken und Bauch (Frauen) – ACS; Ausstrahlung in Nacken oder Rücken – akutes Aortensyndrom","Weitere Symptome: Atemnot, Husten, Tachypnoe, Tachykardie, Zyanose – Lungenembolie; Atemnot, Übelkeit, Schwindel, Blässe, Schweißausbruch – ACS"],
 r:{d:"N", s:"Akute Thoraxschmerzen – Anamnese (OPQRST)", p:"S. 11–12"}},
{t:"Herz-Kreislauf & Schock", q:"Wie untersuchen Sie einen Patienten mit Herz-Kreislauf-Notfall, welche allgemeinen Maßnahmen ergreifen Sie und wann geben Sie Sauerstoff?",
 a:["Untersuchung nach xABCDE mit Fokus auf C, SAMPLER","Inspektion: Stauungszeichen oder Ödeme? Farbe, Beschaffenheit und Temperatur der Haut?","Auskultation: Herzfrequenz und -rhythmus, Rasselgeräusche oder Atemnebengeräusche?","Palpation: Puls, Ödeme, Nagelbettprobe","Maßnahmen: Basismaßnahmen, insbesondere Auskultieren und EKG; Lagerung entsprechend der Symptome; enge Kleidung öffnen, Frischluftzufuhr, Wärmeerhalt; Patient nicht aufstehen lassen und nicht alleine lassen; beruhigen – er hat Todesangst; i.v.-Zugang vorbereiten","Sauerstoff nur bei Atemnot, Zyanose, Bewusstlosigkeit, Herzinsuffizienzzeichen, kardialem Schock und Rhythmusstörungen oder SpO2 < 92 %"],
 r:{d:"N", s:"Herz-Kreislauf-Notfälle – Untersuchung, Maßnahmen", p:"S. 12"}},
{t:"Herz-Kreislauf & Schock", q:"Was ist die koronare Herzkrankheit (KHK) und welche Manifestationen werden unterschieden? Worin unterscheiden sich Angina pectoris und Myokardinfarkt?",
 a:["KHK = Folge einer Arteriosklerose der Koronararterien, die zu einer Unterversorgung der Herzmuskulatur mit Sauerstoff geführt hat","Chronisches Koronarsyndrom (stabile Angina pectoris): Beschwerden unter Belastung, mit Nitrospray behandelbar","Akutes Koronarsyndrom (ACS): instabile Angina pectoris (erstmalige Beschwerden) und Myokardinfarkt","Myokardinfarkt: Absterben von Herzmuskelzellen durch Minderdurchblutung (Ischämie) einer oder mehrerer Herzkranzarterien; der akute Myokardinfarkt (AMI) führt zu Funktionseinschränkungen bis zum Herz-Kreislauf-Stillstand, abgestorbenes Gewebe vernarbt und wird zu Bindegewebe","Unterschied: Angina pectoris ist reversibel, der Myokardinfarkt ist eine dauerhafte Schädigung des Herzmuskels"],
 r:{d:"N", s:"Koronare Herzkrankheit (KHK)", p:"S. 12–13"}},
{t:"Herz-Kreislauf & Schock", q:"Unterscheiden Sie NSTEMI und STEMI. Wie führt die Grunderkrankung Arteriosklerose zur KHK und welche Risikofaktoren gibt es?",
 a:["NSTEMI: keine ST-Strecken-Hebungen im EKG – nur die innere Schicht des Herzmuskels ist unterversorgt","STEMI: ST-Strecken-Hebungen im EKG – innere und äußere Schicht sind unterversorgt","Arteriosklerose: Cholesterin, Kalk und andere Substanzen lagern sich in der Gefäßwand (Endothel) ab → Gefäße werden zunehmend eingeengt und versteift → Sauerstoffversorgung chronisch beeinträchtigt → Gefahr eines Gefäßverschlusses","Risikofaktoren: Bluthochdruck, Diabetes, Fettstoffwechselstörungen, Adipositas"],
 r:{d:"N", s:"KHK – Myokardinfarkt, Ursachen", p:"S. 13"}},
{t:"Herz-Kreislauf & Schock", q:"Nennen Sie die Symptome eines akuten Koronarsyndroms einschließlich atypischer Beschwerden sowie seine Komplikationen.",
 a:["Brustschmerzen – stechend und brennend oder drückend, ggf. mit Ausstrahlung","Atemnot, Todesangst, kaltschweißige Haut, Blässe, Übelkeit, Erbrechen, Schwindel, Zyanose","Atypisch auch allgemeine Schwäche oder Schwindel, Bauchschmerzen","Komplikationen: Herzrhythmusstörungen (v.a. Kammerflimmern), Lungenödem, kardiogener Schock","Differenzialdiagnose: alle Ursachen für akute Thoraxschmerzen"],
 r:{d:"N", s:"KHK – Symptomatik ACS, Komplikationen", p:"S. 13"}},
{t:"Herz-Kreislauf & Schock", q:"Welche Maßnahmen ergreifen Sie beim akuten Koronarsyndrom? Nennen Sie auch Lagerung, Sauerstoffgrenze und die erweiterte Therapie.",
 a:["Vitalfunktionen sichern nach xABCDE, Basismonitoring","Lagerung mit erhöhtem Oberkörper (15–35°)","Zügige Nachforderung des Notarztes","Enge Kleidung öffnen, Frischluftzufuhr, beruhigen und betreuen","Sauerstoffgabe bei SpO2 < 90 %","12-Kanal-EKG: ST-Strecken-Hebung?","i.v.-Zugang und VEL vorbereiten, Reanimationsbereitschaft","Erweitert: Herzkatheterintervention (PCI) oder Lysetherapie"],
 r:{d:"N", s:"KHK – Anamnese und Maßnahmen", p:"S. 13"}},
{t:"Herz-Kreislauf & Schock", q:"Erklären Sie die Entstehung einer Lungenembolie und warum sie zum kardialen Schock führen kann. Worin unterscheiden sich Thrombus und Embolus?",
 a:["Lungenembolie = Folge eines Embolus (abgelöstes Gerinnsel), der eine oder mehrere Lungenarterien verlegt; Ursache ist ein Thrombus aus einer tiefen Bein- oder Beckenvene","Das Gerinnsel gelangt über die untere Hohlvene und das rechte Herz in den Lungenkreislauf und bleibt in einer Lungenarterie stecken","Die Lungenarterie kann kein O2-armes Blut mehr zur Lunge führen, das Blut staut sich vor dem Verschluss → plötzliche Druckbelastung des rechten Herzens, das mit höherem Schlagvolumen und höherer Frequenz auszugleichen versucht","Bei Verschluss einer großen Lungenarterie: akute Überlastung des rechten Herzens (akute Rechtsherzinsuffizienz) → zu wenig Blut im linken Herzen → kardialer Schock","Eingeschränkter Gasaustausch → arterielle Hypoxämie und Hypoxie, dadurch Tachypnoe","Thrombus bleibt an seiner Stelle und verstopft, Embolus wandert"],
 r:{d:"N", s:"Lungenembolie", p:"S. 13–14"}},
{t:"Herz-Kreislauf & Schock", q:"Nennen Sie Symptome, Komplikationen und Maßnahmen bei einer Lungenembolie.",
 a:["Plötzliche Atemnot, Angst, Unruhe, Beklemmungsgefühl","Atemabhängige Thoraxschmerzen, v.a. beim Einatmen","Herzrasen und beschleunigte Atmung, plötzlicher RR-Abfall (< 90) bis zum Schock","Gestaute Halsvenen (bei akuter Rechtsherzinsuffizienz), zentrale Zyanose, plötzliche Bewusstlosigkeit","Komplikationen: kardialer Schock bei akuter Rechtsherzinsuffizienz, Herz-Kreislauf-Stillstand","Maßnahmen: xABCDE und Basismonitoring mit 12-Kanal-EKG; Oberkörper erhöht bei Bewusstsein; maximale Sauerstoffgabe; Notarzt bei Lebensgefahr oder Blutdruckabfall (ggf. kardialer Schock); i.v.-Zugang vorbereiten, Reanimationsbereitschaft"],
 r:{d:"N", s:"Lungenembolie – Symptomatik, Maßnahmen", p:"S. 14"}},
{t:"Herz-Kreislauf & Schock", q:"Was ist eine Herzinsuffizienz? Ordnen Sie die Symptome dem Rechts- und Linksherzversagen (Vorwärts- und Rückwärtsversagen) zu und nennen Sie die Maßnahmen.",
 a:["Einschränkung der Pumpfunktion und dadurch der körperlichen Belastbarkeit: linker oder rechter Ventrikel wirft in der Systole nicht genügend Blut aus – Vorwärts- und Rückwärtsversagen","Ursachen: KHK, arterielle Hypertonie, chronische Lungenerkrankungen, Folge eines Herzinfarkts oder einer hypertensiven Krise","Allgemein: massive Atemnot (auch in Ruhe), Angst, Unruhe, Tachykardie, periphere Zyanose","Akute Rechtsherzinsuffizienz: gestaute Halsvenen und/oder Ödeme","Akute Linksherzinsuffizienz – Vorwärtsversagen: Verwirrtheit, blasse und kalte Haut; Rückwärtsversagen: kardiales Lungenödem mit Atemnot, schaumigem Auswurf, Rasselgeräuschen und Husten","Maßnahmen: xABCDE und Basismonitoring, Oberkörper erhöht bei Bewusstsein, Notarzt bei akuter Herzinsuffizienz, i.v.-Zugang vorbereiten, Reanimationsbereitschaft, ggf. CPAP-Beatmung"],
 r:{d:"N", s:"Herzinsuffizienz (Herzmuskelschwäche)", p:"S. 14–15"}},
{t:"Herz-Kreislauf & Schock", q:"Definieren Sie Herzrhythmusstörungen. Nennen Sie Beispiele für bradykarde und tachykarde Störungen, die typischen Symptome und Ihre Maßnahmen.",
 a:["Frequenz oder Rhythmus weichen von den Normwerten (60–100/min) ab","Bradykardie < 60/min, z.B. AV-Block, Sinusbradykardie, Asystolie (= Nulllinie)","Tachykardie > 100/min in Ruhe, z.B. Sinustachykardie, Vorhof-/Kammerflimmern","Außerdem Arrhythmie oder Extrasystolen","Ursachen u.a.: Erkrankungen des Herzens (KHK, Myokardinfarkt, Herzmuskelentzündung), Lungenembolie, Schilddrüsenfunktionsstörung","Symptome: Schwindel; bradykard – Schläfrigkeit, Atemnot bei geringer Anstrengung, blasse zyanotische Haut; tachykard – Herzrasen ohne Anstrengung, Unruhe, Tachypnoe","Maßnahmen: xABCDE und Basismonitoring, Oberkörper erhöht bei Bewusstsein, Notarzt bei akuter Lebensgefahr, Reanimationsbereitschaft"],
 r:{d:"N", s:"Herzrhythmusstörungen", p:"S. 15"}},
{t:"Herz-Kreislauf & Schock", q:"Definieren Sie arterielle Hypertonie und hypertensive Entgleisung. Nennen Sie Auslöser, Symptome, Komplikationen und Maßnahmen der hypertensiven Entgleisung.",
 a:["Arterielle Hypertonie: Erhöhung des arteriellen Blutdrucks in Ruhe; Ursachen z.B. Genetik, Stress, Rauchen, Alter, wenig Bewegung und Übergewicht","Hypertensive Entgleisung: krisenhafter Blutdruckanstieg > 180 mmHg systolisch / 120 mmHg diastolisch; Auslöser: Incompliance, psychischer Stress, Alkohol, Drogen","Symptome: sehr hoher Blutdruck, hochroter Kopf → Funktionsstörung der Organe mit Kopfschmerzen, Nasenbluten, neurologischen Symptomen (z.B. Sehstörungen, Schwindel, Krampfanfälle), Übelkeit und Erbrechen, Ohrensausen, Atemnot, Thoraxschmerzen","Komplikationen: Hirnblutung, ischämischer Insult, Anstieg des Hirndrucks, akute Linksherzinsuffizienz, akutes Koronarsyndrom, akutes Aortensyndrom, akutes Nierenversagen","Maßnahmen: xABCDE und Basismonitoring, Herzbettlagerung (30°), Notarzt bei lebensbedrohlichen Symptomen wie Bewusstseinstrübung oder Thoraxschmerzen, i.v.-Zugang vorbereiten"],
 r:{d:"N", s:"Arterielle Hypertonie und Hypertensive Entgleisung", p:"S. 15–16"}},
{t:"Herz-Kreislauf & Schock", q:"Was ist eine Perikardtamponade, wie führt sie zum Schock und woran erkennen Sie sie?",
 a:["Ansammlung von Flüssigkeit (Blut oder Erguss) im Herzbeutel, die die mechanische Herzaktion verhindert und sich zum kardialen Schock entwickelt","Füllt sich der Herzbeutel, hat das Herz nicht mehr genug Platz, sich in der Diastole ausreichend zu füllen → das Blut staut sich zurück, das Herzzeitvolumen sinkt bis zum obstruktiven Schock","Ursachen: Herzbeutelentzündung (Perikarditis), Einblutung bei Thoraxtrauma, Ruptur der Ventrikelwand als Folge eines Myokardinfarkts","Symptome: Blutdruckabfall, Blässe, Kaltschweißigkeit, gestaute Halsvenen, abgeschwächte Herztöne","Maßnahmen: xABCDE und Basismonitoring, Oberkörper hochlagern, Sauerstoffgabe, i.v.-Zugang vorbereiten, ggf. Notarzt nachfordern"],
 r:{d:"N", s:"Perikardtamponade", p:"S. 16"}},
{t:"Herz-Kreislauf & Schock", q:"Beschreiben Sie Entstehung, Symptome und Maßnahmen beim akuten Aortensyndrom. Worauf achten Sie beim Transport?",
 a:["Die innere Schicht der Aortenwand reißt ein, Blut dringt in die mittlere Schicht ein und breitet sich aus; der blutgefüllte Kanal kann abzweigende Arterien verlegen oder zur Ruptur der Aorta führen","Ursachen: Aufspaltung der Gefäßwandschichten durch thorakale Aortendissektion, Verletzung der Aorta; Risikofaktor Arteriosklerose","Symptome: plötzlicher thorakaler Vernichtungsschmerz mit Ausstrahlung in Rücken oder Schulterblätter, Blutdruckdifferenz zwischen linkem und rechtem Arm, hämorrhagischer Schock mit Blutdruckabfall und Tachykardie, Symptome von Organschädigungen","Maßnahmen: Diagnose schwierig! xABCDE und Basismonitoring, Schocklagerung, ggf. Immobilisation, Sauerstoffgabe, i.v.-Zugang und VEL vorbereiten","Bei Verdacht Notarzt nachfordern und schnellstmöglich, aber ganz vorsichtig in die Klinik transportieren – zur Vermeidung einer Aortenruptur"],
 r:{d:"N", s:"Akutes Aortensyndrom", p:"S. 16–17"}},
{t:"Herz-Kreislauf & Schock", q:"Nennen Sie die reversiblen Ursachen eines Herz-Kreislauf-Stillstands (4 H und HITS), seine Symptome und Ihre Maßnahmen.",
 a:["Herz-Kreislauf-Stillstand = plötzlicher Ausfall der Herzfunktion und damit der Blutzirkulation","4 H: Hypoxie, Hypovolämie, Hyperkaliämie, Hypothermie","HITS: Herzbeuteltamponade, Intoxikation, Thromboembolie, Spannungspneumothorax","Symptome: Pulslosigkeit, Atemstillstand oder Schnappatmung, kein Muskeltonus, extrem blasse bis grau-weißliche Haut, weite, zunehmend lichtstarre Pupillen, Hypothermie","Maßnahmen: Bewusstseinskontrolle, Atemkontrolle, Reanimation (Herzdruckmassage, Beatmung, Defibrillation), Notarzt nachfordern","Erfolgreiche Reanimation = ROSC („Return of spontaneous circulation“)"],
 r:{d:"N", s:"Herz-Kreislauf-Stillstand", p:"S. 17"}},

/* ===== Gastrointestinale Notfälle ===== */
{t:"Gastrointestinale Notfälle", q:"Nennen Sie die Leitsymptome des akuten Abdomens und ordnen Sie Schmerzcharakter und zeitlichen Verlauf möglichen Ursachen zu.",
 a:["Leitsymptome: akute starke Bauchschmerzen, Abwehrspannung der Bauchdecke, Veränderung des Stuhlgangs, Übelkeit und Erbrechen, Kreislaufinstabilität","Dumpf, drückend – Appendizitis, Pankreatitis","Krampfartig, heftig, oft mit Übelkeit – Gallenkolik, Nierenkolik","Brennend – Entzündungen von Magen oder Speiseröhre; stechend, drückend – Herzinfarkt","Verlauf: Kolikschmerzen nehmen wellenartig zu; Entzündungsschmerzen nehmen stetig zu, Bewegungen verschlimmern; Perforationsschmerzen beginnen plötzlich und heftig – Vernichtungsschmerz beim Durchbruch eines Organs"],
 r:{d:"N", s:"Gastrointestinale Notfälle – Leitsymptome, Anamnese", p:"S. 17–18"}},
{t:"Gastrointestinale Notfälle", q:"Wie untersuchen Sie den Bauch bei akuten Bauchschmerzen? Nennen Sie die Einteilung der Schmerzlokalisation und die vier Untersuchungstechniken mit ihren Befunden.",
 a:["Schmerzlokalisation nach 4 Quadranten und Mittelbauch","Inspektion: Hämatome, Hautkolorit, Vorwölbungen, aufgetriebenes Abdomen","Auskultation: Darmgeräusche abgeschwächt, verstärkt oder fehlend","Palpation: Bruchpforten, Druckschmerz, Loslassschmerz, Gesichtsausdruck","Perkussion: hohles oder schwappendes Geräusch"],
 r:{d:"N", s:"Gastrointestinale Notfälle – Anamnese und Untersuchung", p:"S. 18"}},
{t:"Gastrointestinale Notfälle", q:"Ordnen Sie den Bauchregionen typische Ursachen akuter Bauchschmerzen zu (Abbildung zur Schmerzlokalisation).",
 a:["Rechter Oberbauch: u.a. Cholezystitis, Cholelithiasis, Nierenkolik","Linker Oberbauch: u.a. akutes Koronarsyndrom/Myokardinfarkt, Aortenaneurysmaruptur, Pankreatitis, Nierenkolik, perforiertes Magengeschwür","Mittelbauch: u.a. mechanischer Ileus, Appendizitis, Pankreatitis, Mesenterialinfarkt, Volvulus/Invagination, Stoffwechselerkrankungen (z.B. diabetische Ketoazidose), Aortenaneurysmaruptur","Rechter Unterbauch: u.a. Appendizitis, Divertikulitis, Eileiterschwangerschaft, Ovarialtorsion, Hodentorsion, Hernieneinklemmung","Linker Unterbauch: u.a. Divertikulitis, Aortenaneurysmaruptur, Eileiterschwangerschaft, Ovarialtorsion, Hodentorsion, Hernieneinklemmung","Alle Quadranten: u.a. Abdominaltrauma"],
 r:{d:"N", s:"Gastrointestinale Notfälle – Schmerzlokalisation (Abbildung)", p:"S. 18"}},
{t:"Gastrointestinale Notfälle", q:"Welche Rückschlüsse ziehen Sie beim akuten Abdomen aus dem Aussehen von Erbrochenem und Stuhl? Was erfragen Sie außerdem?",
 a:["Erbrochenes grünlich-gelb – Magen-Darm-Infektion","Koterbrechen – Ileus","Blut im Erbrochenen – schwere Erkrankung von Magen oder Speiseröhre, akute Lebensgefahr!","Stuhl hell bis lehmfarben – Gallenabflussstörung","Hell- bis dunkelrote Auflagerungen – Blutung im Enddarm oder Analbereich","Schwarzer Teerstuhl – Blutung im oberen Verdauungstrakt","Außerdem: Übelkeit, Erbrechen? Häufigkeit des Stuhlgangs heute und in der letzten Woche? Ggf. Schwangerschaft"],
 r:{d:"N", s:"Gastrointestinale Notfälle – Anamnese", p:"S. 18"}},
{t:"Gastrointestinale Notfälle", q:"Welche Maßnahmen ergreifen Sie bei einem Patienten mit akutem Abdomen?",
 a:["Basismaßnahmen und Basismonitoring","Lagerung mit Entlastung der Bauchdecke","Ess-, Trink- und Rauchverbot","Je nach Kreislaufsituation i.v.-Zugang vorbereiten","Sauerstoffgabe bei potentiell kritischen Patienten und SpO2 < 92 %"],
 r:{d:"N", s:"Gastrointestinale Notfälle – Maßnahmen", p:"S. 18"}},
{t:"Gastrointestinale Notfälle", q:"Unterscheiden Sie obere und untere Gastrointestinalblutung nach Lokalisation und Ursachen. Welche Hinweise liefern Erbrochenes und Stuhl?",
 a:["Obere GI-Blutung: Blutung in Speiseröhre, Magen oder Zwölffingerdarm – Ursachen: Magen- oder Darmgeschwüre, Ösophagusvarizen","Untere GI-Blutung: Blutung in Dünndarm, Dickdarm oder Enddarm – Ursachen: Tumore, Entzündungen, Hämorrhoiden, chronisch-entzündliche Darmerkrankungen","Schwarzer Teerstuhl: Blutung im oberen Verdauungstrakt","Hell- bis dunkelrote Auflagerungen auf dem Stuhl: Blutung im Enddarm oder Analbereich","Blut im Erbrochenen: schwere Erkrankung von Magen oder Speiseröhre, akute Lebensgefahr"],
 r:{d:"N", s:"Gastrointestinale Blutungen", p:"S. 18"}},
{t:"Gastrointestinale Notfälle", q:"Beschreiben Sie Ursachen, Symptome und die gefürchtete Komplikation einer Appendizitis.",
 a:["Appendizitis = Entzündung des Blinddarms","Ursachen: bakterielle Infektion des Darms, die auf Blinddarm und Wurmfortsatz übergeht; Verschluss des Wurmfortsatzes durch Kotsteine, Parasiten oder Fremdkörper","Symptome: Appetitlosigkeit, Übelkeit, Erbrechen, Fieber, Stuhlunregelmäßigkeiten","Zunehmende Bauchschmerzen: erst um den Bauchnabel und im Oberbauch, später im rechten Unterbauch","Komplikation: Perforation der Appendixwand → Darminhalt und eitriges Sekret treten in den Bauchraum aus → Entzündung des Bauchfells (Peritonitis)"],
 r:{d:"N", s:"Appendizitis", p:"S. 19"}},
{t:"Gastrointestinale Notfälle", q:"Was ist eine akute Pankreatitis? Nennen Sie Ursache, Symptome, Komplikation und die wichtige Differenzialdiagnose.",
 a:["Akute Pankreatitis = Entzündung der Bauchspeicheldrüse","Ursache: Verlegung der ableitenden Gallenwege durch Gallensteine, seltener durch Tumore","Symptome: akute, starke gürtelförmige Oberbauchschmerzen mit Ausstrahlung in die Flanken","Begleitsymptome: Fieber, Übelkeit, geblähter Bauch, Flüssigkeitsansammlung im Bauch (Aszites)","Komplikation: hypovolämischer Schock durch Einblutungen in der Haut der Flanken","Differenzialdiagnose: akutes Koronarsyndrom bei Frauen!"],
 r:{d:"N", s:"Akute Pankreatitis", p:"S. 19"}},
{t:"Gastrointestinale Notfälle", q:"Nennen Sie die Leitsymptome von Lebererkrankungen und beschreiben Sie Hepatitis, Leberverfettung und Leberzirrhose.",
 a:["Aszites: Ansammlung von Flüssigkeit in der Bauchhöhle – Bauch wirkt geschwollen, rasche Gewichtszunahme, Nabel nach außen gewölbt","Ikterus/Gelbsucht: gelbliche Verfärbung von Haut und Schleimhäuten wegen eines erhöhten Bilirubinspiegels, oft mit quälendem Juckreiz","Hepatitis: akute oder chronische Entzündung des Lebergewebes als Folge einer viralen Infektion","Leberverfettung: Fette lagern sich im Lebergewebe ein und beeinträchtigen die Funktion, kann zur Leberzirrhose führen","Leberzirrhose: funktionsfähiges Lebergewebe wird unumkehrbar in nicht funktionales, knotig-narbiges Bindegewebe umgewandelt"],
 r:{d:"N", s:"Lebererkrankungen", p:"S. 19–20"}},
{t:"Gastrointestinale Notfälle", q:"Was ist eine hepatische Enzephalopathie? Nennen Sie Ursachen, Symptome und Maßnahmen.",
 a:["Verminderte oder fehlende Entgiftungsfunktion der Leber → Anstieg neurotoxischer Stoffe im Blut → schwerwiegende Funktionsstörungen des Gehirns (bis zum Leberkoma)","Ursachen: akutes Leberversagen, Vergiftungen","Symptome: Schläfrigkeit, Verwirrung, Konzentrationsstörungen, erhöhte Atemfrequenz, süßlich-fauliger Mundgeruch","Maßnahmen: Vitalfunktionen sichern und Basismonitoring, Notarzt nachfordern, Lagerung mit erhöhtem Oberkörper, Suche nach Verletzungen, Sauerstoffgabe, i.v.-Zugang vorbereiten"],
 r:{d:"N", s:"Hepatische Enzephalopathie und Leberkoma", p:"S. 20"}},
{t:"Gastrointestinale Notfälle", q:"Welche Symptome und Komplikationen kann ein Gallensteinleiden verursachen?",
 a:["Ursache: Gallensteine in der Gallenblase und/oder im großen Gallengang","Symptome: anfallsartige, starke Kolikschmerzen im rechten/mittleren Oberbauch","Gallenkolik durch Verlegung der Gallenwege","Entzündung der Gallenblase oder der Gallenwege – Gallensteine erhöhen das Risiko für Bakterien","Akute Pankreatitis durch Gallensteine im gemeinsamen Ausführungsgang von Gallenwegen und Pankreas","Mechanischer Ileus durch einen Gallenstein im Darm"],
 r:{d:"N", s:"Gallensteinleiden", p:"S. 20"}},
{t:"Gastrointestinale Notfälle", q:"Was ist ein Ileus? Nennen Sie Ursachen und Symptome des mechanischen Ileus und die wichtigste Gefahr.",
 a:["Ileus (Darmverschluss) = komplette Unterbrechung der Darmpassage; man unterscheidet mechanischen und paralytischen Ileus","Ursachen des mechanischen Ileus: Verwachsungen nach OP, Tumore, Fremdkörper, Gallensteine, entzündliche Verengungen bei chronischen Darmentzündungen, Hernie (Eingeweidebruch)","Symptome: fehlender Stuhlabgang, aufgeblähtes Abdomen, schwer lokalisierbare kolikartige Bauchschmerzen, Übelkeit und Erbrechen","Hinweis im Erbrochenen: Koterbrechen","Achtung Schockgefahr → Volumensubstitution"],
 r:{d:"N", s:"Darmverschluss (Ileus) / Gastrointestinale Notfälle – Anamnese", p:"S. 20–21 und 18"}},
{t:"Gastrointestinale Notfälle", q:"Was ist ein Bauchaortenaneurysma? Unterscheiden Sie gedeckte und freie Ruptur und nennen Sie die Maßnahmen.",
 a:["Krankhafte Erweiterung der Bauchaorta, die reißen kann (Ruptur)","Entstehung: z.B. durch Arteriosklerose verkalkte Gefäßwand wird weniger elastisch, das Gefäß weitet sich bis zur Ausbeulung (= Aneurysma) mit der Gefahr zu reißen","Gedeckte Ruptur: Blutung ist durch umliegende Strukturen abgedeckt – Schmerzen oder dumpfes Drücken in Rücken oder Flanken","Freie oder offene Ruptur: potentiell innerhalb weniger Minuten tödlich durch inneres Verbluten","Maßnahmen: insbesondere Volumengabe und Transport in eine Klinik mit Gefäßchirurgie – Achtung: vorsichtiger Transport, da Gefahr einer Ruptur!"],
 r:{d:"N", s:"Bauchaortenaneurysma", p:"S. 21"}},

/* ===== Traumatologische Notfälle ===== */
{t:"Traumatologische Notfälle", q:"Welche Maßnahmen ergreifen Sie bei Verletzungen von Gelenken, Sehnen und Bändern? Erklären Sie dabei die PECH-Regel im Detail.",
 a:["Distorsion (Verstauchung): Überdehnung durch indirekte Gewalteinwirkung – Schwellung, Schmerz, eingeschränkte Beweglichkeit, Einblutung","Luxation (Verrenkung): Verlust des Kontakts zwischen zwei oder mehr Knochen – federnde schmerzhafte Bewegungsunfähigkeit, leere Gelenkpfanne durch Fehlstellung, Schonhaltung, Hämatom","Maßnahmen: Vitalparameter und Basismonitoring, DMS-Kontrolle, Wärmeerhalt, i.v.-Zugang vorbereiten, ggf. Notarzt für die Analgesie","PECH: Pause – Eis (kurzfristige Kühlung ca. 20–30 Minuten ohne direkten Hautkontakt) – Compression – Hochlagern"],
 r:{d:"N", s:"Verletzungen der Gelenke, Sehnen und Bänder", p:"S. 21"}},
{t:"Traumatologische Notfälle", q:"Definieren Sie Fraktur und nennen Sie Ursachen, sichere und unsichere Frakturzeichen sowie Ihre Maßnahmen.",
 a:["Fraktur = teilweise oder vollständige Unterbrechung der Kontinuität eines Knochens in zwei oder mehrere Bruchstücke (Fragmente); offene und geschlossene Frakturen","Ursachen: Folge eines Traumas; geringe Gewalteinwirkung bei geschädigter Knochengrundsubstanz (z.B. Osteoporose)","Sichere Zeichen: abnorme Beweglichkeit, Fehlstellung, Krepitation, sichtbare Knochenteile","Unsichere Zeichen: Schmerzen, Rötung, Schwellung, Funktionsstörung, Schonhaltung","Maßnahmen: Vitalfunktionen sichern, Basismonitoring, Schockprophylaxe, wiederholte pDMS-Kontrollen, sorgfältige Wundversorgung und Infektionsschutz bei offenen Frakturen, ggf. Notarzt für Analgosedierung, achsengerechte Reposition, Ruhigstellung"],
 r:{d:"N", s:"Verletzungen der Knochen (Fraktur)", p:"S. 22"}},
{t:"Traumatologische Notfälle", q:"Welche Möglichkeiten der Blutstillung nennt die Zusammenfassung? Wie versorgen Sie eine Amputationsverletzung und das Amputat?",
 a:["Blutstillung: manuelle Kompression, Druckverband mit steriler Wundauflage, Druckpolster und Binde, Tourniquet, Hämostyptika, Wundtamponade, Wundklammer, großzügige Volumentherapie","Amputation = teilweise oder vollständige Abtrennung einer Extremität vom Körper","Extremität hochlagern und Blutung stillen","Amputat steril einwickeln und für den Transport in ein Replantations-Set verpacken","Bei subtotaler Amputation die Verbindung zwischen Körper und Amputat keinesfalls trennen","Zähne wie ein Amputat behandeln"],
 r:{d:"N", s:"Blutungen und Blutstillung, Amputationen", p:"S. 22"}},
{t:"Traumatologische Notfälle", q:"Erklären Sie, wie es beim Schädel-Hirn-Trauma zur sekundären Schädigung kommt, und teilen Sie das SHT nach Art und Schweregrad ein.",
 a:["SHT = Verletzung durch spitze oder stumpfe Gewalteinwirkung auf den Kopf; Ursachen: Stürze, Verkehrsunfälle, Gewaltdelikte","Primäre Schädigung: direkte Verletzung der Strukturen im Schädel","Sekundäre Schädigung: das Hirngewebe schwillt an, Blut tritt aus verletzten Gefäßen aus; die Blutung verdrängt das Hirngewebe, das in der festen knöchernen Schädelhöhle nicht ausweichen kann und zusammengequetscht wird → Hirndruck steigt, Durchblutung sinkt","Geschlossenes SHT: harte Hirnhaut (Dura mater) intakt; offenes SHT: Dura mater eröffnet, Gehirn hat Verbindung nach außen – Infektionsrisiko!","Leichtes SHT (Gehirnerschütterung): reversible Funktionsstörung ohne nachweisbare organische Schädigung, Bewusstlosigkeit < 30 Minuten","Mittelschweres SHT (Gehirnprellung): nachweisbare organische Schädigung, Bewusstlosigkeit > 30 Minuten","Schweres SHT (Gehirnquetschung): Schädigung des Gehirns durch Druckanstieg, tiefe, länger anhaltende Bewusstlosigkeit"],
 r:{d:"N", s:"Schädel-Hirn-Trauma – Einteilung", p:"S. 22–23"}},
{t:"Traumatologische Notfälle", q:"Nennen Sie Symptome eines Schädel-Hirn-Traumas und Ihre Maßnahmen.",
 a:["Bewusstseinsstörungen bis Bewusstlosigkeit; Amnesie, Kopfschmerzen, Schwindel, Übelkeit, Erbrechen","Neurologische Ausfälle, auch Lähmungen, Krampfanfälle; Pupillendifferenz","Tast- oder sichtbare Stufenbildung am Schädel, evtl. Austritt von Hirnmasse; Ausfluss von Liquor aus Ohr oder Nase; sichtbare Wunden im Kopfbereich, Hämatome","Maßnahmen: xABCDE und Basismonitoring, insbesondere BZ und GCS; Hinterkopf untersuchen; Notarzt nachfordern","Großzügige Sauerstoffgabe, Wärmeerhalt; i.v.-Zugang und VEL vorbereiten, Absaugbereitschaft, ggf. Intubation vorbereiten","Ruhigstellung der HWS, Lagerung mit erhöhtem Oberkörper, sterile Wundversorgung, Transport mit Spineboard oder Vakuummatratze"],
 r:{d:"N", s:"Schädel-Hirn-Trauma – Symptomatik, Maßnahmen", p:"S. 23"}},
{t:"Traumatologische Notfälle", q:"Unterscheiden Sie epidurales Hämatom, subdurales Hämatom und intrazerebrale Blutung nach ihrer Lage.",
 a:["Epidurales Hämatom (EDH): Blutung zwischen Dura mater und Schädelknochen","Subdurales Hämatom (SDH): Blutung zwischen Dura mater und Arachnoidea","Intrazerebrale Blutung (ICB): Einblutung direkt im Hirngewebe","Subdurales und epidurales Hämatom sind in der Regel Folge eines SHT"],
 r:{d:"N", s:"Schädel-Hirn-Trauma – Intrakranielle Blutungen / Subdurales und Epidurales Hämatom", p:"S. 23 und 32"}},
{t:"Traumatologische Notfälle", q:"Nennen Sie die „tödlichen 6“ und die „versteckten 6“ beim Thoraxtrauma.",
 a:["Tödliche 6: Atemwegsverlegung, instabiler Thorax, Herzbeuteltamponade/Perikardtamponade, Pneumothorax (offen oder geschlossen), Spannungspneumothorax, Hämatothorax","Versteckte 6: Herzkontusion (Herzprellung), Lungenkontusion (Lungenquetschung oder Lungenprellung), Aortenruptur, Zwerchfellruptur, Ösophagusruptur, Verletzung von Trachea oder Bronchien"],
 r:{d:"N", s:"Thoraxtraumata", p:"S. 24"}},
{t:"Traumatologische Notfälle", q:"Erklären Sie Entstehung, Folgen und Symptome von Pneumothorax, Hämatothorax und traumatischer Herzbeuteltamponade.",
 a:["Pneumothorax: der Unterdruck im Pleuraspalt sorgt für die Belüftung; bei einer Verletzung dringt Luft ein, der Unterdruck wird aufgehoben und das Lungengewebe kollabiert → der Lungenflügel fällt für den Gasaustausch aus (Hypoxämie), die Lungengefäße verengen sich → Durchblutungswiderstand und Belastung des rechten Herzens steigen; Symptome: plötzliche, einseitige Thoraxschmerzen und Luftnot","Hämatothorax: Einblutung in den Pleuraspalt – pro Thoraxhälfte bis zu 3 l Blut → hämorrhagischer Schock bis Kreislaufstillstand, zusätzlich Kompression der Lunge → Hypoxämie und Ateminsuffizienz; Symptome: Zyanose, Ateminsuffizienz, fehlende oder abgeschwächte Atemgeräusche auf der verletzten Seite, Schockzeichen","Herzbeuteltamponade: durch Prellung des Herzens an der Innenseite des Thorax reißen Gefäße, der Herzbeutel füllt sich mit Blut, das Herz hat nicht mehr genug Platz → Pumpversagen mit obstruktivem Schock, Herz-Kreislauf-Stillstand; Symptome: rasch einsetzende Hypotonie mit Tachykardie, Dyspnoe, gestaute Halsvenen"],
 r:{d:"N", s:"Thoraxtraumata – Die tödlichen 6", p:"S. 24"}},
{t:"Traumatologische Notfälle", q:"Welche Maßnahmen ergreifen Sie beim Thoraxtrauma? Wie lagern Sie den Patienten und wie gehen Sie mit einem steckenden Fremdkörper um?",
 a:["Vitalfunktionen sichern nach xABCDE, Basismonitoring, Auskultation beider Lungen","Frühzeitige Sauerstoffgabe","i.v.-Zugang und VEL vorbereiten, Wärmeerhalt","Lagerung mit erhöhtem Oberkörper auf die verletzte Thoraxseite – außer bei Verdacht auf Wirbelsäulenverletzung: Rückenlage und Immobilisation","Notarzt nachfordern; bei Ateminsuffizienz Intubation und Narkose vorbereiten","Wundversorgung: Fremdkörper nicht entfernen, locker unterpolstern und fixieren","Schnellstmöglicher Transport"],
 r:{d:"N", s:"Thoraxtraumata – Maßnahmen", p:"S. 24"}},
{t:"Traumatologische Notfälle", q:"Warum ist ein Beckentrauma so gefährlich? Erklären Sie das KISS-Schema und nennen Sie die Maßnahmen.",
 a:["Das Knochenmark im Beckenring ist sehr gut durchblutet – nahezu das gesamte Blutvolumen kann dorthin verloren gehen","Ursachen: Überrollen, Verschüttung, Sturz aus großer Höhe","Symptome: Schmerzen in Becken oder Hüfte, „Ameisenlaufen“ oder Lähmungen der Beine","KISS: Kinetik (Unfallmechanismus) – Inspektion (Fehlstellung, Längendifferenz, Prellmarken, Asymmetrie) – Schmerzen – Stabilisierung mit Beckenschlinge","Maßnahmen: xABCDE und Basismonitoring, Sauerstoffgabe, Notarzt nachfordern, i.v.-Zugang und VEL vorbereiten, Wärmeerhalt, Beckenschlinge und manuelle Kompression, pDMS-Kontrollen"],
 r:{d:"N", s:"Beckentrauma", p:"S. 25"}},
{t:"Traumatologische Notfälle", q:"Definieren Sie Polytrauma und erklären Sie die „Golden Hour of Trauma“ sowie die 5 Säulen der Polytrauma-Versorgung.",
 a:["Polytrauma = mehrere Körperregionen oder Organsysteme sind gleichzeitig verletzt, wobei eine Verletzung allein oder die Kombination mehrerer Verletzungen lebensbedrohlich ist","Golden Hour of Trauma: wesentlicher Faktor ist die ZEIT – von der Verletzung bis zur Klinik max. 1 Stunde, am besten per RTH in ein Traumazentrum","Strikt nach xABCDE mit den 5 Säulen, möglichst in 20 Minuten:","1. Stoppen kritischer Blutungen","2. Ausreichende Oxygenierung und Beatmung sicherstellen, ggf. Spannungspneumothorax entlasten","3. Suffizienten Kreislauf durch Volumen- oder Medikamentengabe sicherstellen","4. Analgesie, ggf. Notfallnarkose","5. Immobilisation"],
 r:{d:"N", s:"Polytrauma", p:"S. 25"}},

/* ===== Neurologische Notfälle ===== */
{t:"Neurologische Notfälle", q:"Nennen Sie die Leitsymptome neurologischer Notfälle und beschreiben Sie die Untersuchung mit Fokus auf „D“ sowie die allgemeinen Maßnahmen.",
 a:["Leitsymptome: Bewusstseinsstörungen, Krampfanfälle, Synkope, Schlaganfall; auch Meningismus, Kopfschmerzen, Rückenschmerzen, Lähmungen, Störungen der Sensibilität und Wahrnehmung, Hirndruck- und Einklemmungszeichen","xABCDE und SAMPLER mit Fokus auf D:","Bewusstsein mit AVPU und GCS überprüfen; Orientierung (zeitlich, örtlich, situativ, persönlich)","Sprach- und Sprechvermögen einschätzen, Pupillenreaktion prüfen","Sensibilität und Motorik: pDMS, Kreuzgriff, Arm-Vorhalte-Versuch (Beine)","BEFAST bei Verdacht auf Schlaganfall","Maßnahmen: Basismaßnahmen und Basismonitoring, Lagerung mit erhöhtem Oberkörper, je nach Kreislaufsituation i.v.-Zugang vorbereiten, Sauerstoff bei potentiell kritischen Patienten und SpO2 < 92 %"],
 r:{d:"N", s:"Neurologische Notfälle – Leitsymptome, Untersuchung", p:"S. 26"}},
{t:"Neurologische Notfälle", q:"Was ist eine Bewusstseinsstörung, wie wird sie eingeteilt und welche Gefahr besteht?",
 a:["Die Klarheit des Bewusstseins ist eingeschränkt, der Patient ist nicht vollständig wach","Er kann auf äußere und innere Reize nicht adäquat reagieren, Schutzreflexe können ausfallen → Aspirationsgefahr","Quantitativ (Wachheit/Vigilanz): Benommenheit, Somnolenz, Sopor, Koma","Qualitativ: Bewusstseinstrübung (Verwirrung, keine geordnete Wahrnehmung), Bewusstseinseinengung (Denken eingeschränkt, Handeln funktioniert), Bewusstseinsverschiebung/-erweiterung (gesteigerte Wahrnehmung)"],
 r:{d:"N", s:"Bewusstseinsstörungen", p:"S. 26–27"}},
{t:"Neurologische Notfälle", q:"Welche Fragen stellen Sie bei einer Bewusstseinsstörung (ggf. fremdanamnestisch) und welche Maßnahmen ergreifen Sie?",
 a:["Seit wann besteht die Bewusstseinsstörung? Wurde der Patient allmählich oder plötzlich bewusstlos?","Was ist unmittelbar vorher passiert (Krampf, Beschwerden, Unfall)? Vorerkrankungen? Intoxikation?","Maßnahmen: Umfeld inspizieren, Eigenschutz beachten!","Bewusstseinskontrolle und Vitalfunktionen sichern","Stabile Seitenlage bei Bewusstlosigkeit – Aspirationsgefahr!","Basismonitoring und BZ-Kontrolle, zügige Sauerstoffgabe, i.v.-Zugang und VEL vorbereiten, Notarzt nachfordern","Engmaschige Beobachtung, bei GCS < 9 Intubation vorbereiten"],
 r:{d:"N", s:"Bewusstseinsstörungen – Anamnese, Maßnahmen", p:"S. 27"}},
{t:"Neurologische Notfälle", q:"Definieren Sie epileptischen Anfall, Status epilepticus und Epilepsie und nennen Sie mögliche Auslöser eines Krampfanfalls.",
 a:["Epileptischer Anfall: vorübergehende Funktionsstörung des Gehirns mit starken elektrischen Aktivitäten, die zu motorischen, sensiblen und/oder vegetativen Auffälligkeiten führen; Dauer i.d.R. < 2 Minuten","Status epilepticus: Dauer > 5 Minuten – Gefahr einer Gehirnschädigung und bedrohlichen Hypoxie","Epilepsie: Erkrankung mit wiederholten epileptischen Anfällen","Auslöser z.B.: Fieberkrampf bei Kindern, Schlafmangel, Hypoglykämie, diabetisches Koma, Medikamente oder Incompliance, exzessiver Konsum von Drogen oder Alkohol, schwere körperliche oder emotionale Belastung, flackernde Lichtquellen, Meningitis, SHT, Hirntumor, Sauerstoffmangel im Gehirn, Sonnenstich, Schlaganfall, Eklampsie"],
 r:{d:"N", s:"Krampfanfälle", p:"S. 27"}},
{t:"Neurologische Notfälle", q:"Unterscheiden Sie fokale und generalisierte Anfälle. Nennen Sie Begleiterscheinungen, Differenzialdiagnosen und Ihre Maßnahmen.",
 a:["Fokale Anfälle betreffen Teile des Gehirns: motorische (eine Extremität), sensible (Kribbeln), sensorische (Geruchseindrücke) oder vegetative Symptome – mit oder ohne Bewusstseinsstörung","Generalisierte Anfälle betreffen das gesamte Gehirn: vollständiger Bewusstseinsverlust, Initialschrei und Sturz, der ganze Körper krampft, währenddessen Atemstillstand und Amnesie","Begleiterscheinungen: Zungenbiss, Speichelfluss, Anstieg von Herzfrequenz und Blutdruck, Zyanose, Einnässen; danach Verwirrung und Schläfrigkeit, ggf. längere Schlafphase","Differenzialdiagnosen: Synkope, Sturzattacke, TIA","Maßnahmen: Schutz des Patienten, Eigenschutz! Stabile Seitenlage wegen Aspirationsgefahr; Vitalfunktionen sichern, Basismonitoring, STU; Sauerstoffgabe, Wärmeerhalt; i.v.-Zugang und VEL vorbereiten; Notarzt nachfordern, ggf. Benzodiazepine"],
 r:{d:"N", s:"Krampfanfälle – Symptome, Maßnahmen", p:"S. 27–28"}},
{t:"Neurologische Notfälle", q:"Was ist eine Synkope? Nennen Sie Auslöser, Symptome vor und nach dem Sturz, Differenzialdiagnosen und Maßnahmen.",
 a:["Synkope (Ohnmacht) = plötzlicher, kurzzeitiger Bewusstseinsverlust durch Minderdurchblutung im Gehirn","Auslöser z.B.: Hitze, Volumenmangel, Medikamente, neurologische Erkrankungen, Emotionen, schnelles Aufstehen","Vor dem Sturz: Ohrensausen, Schwäche, Blässe, Schwarzwerden vor Augen, Schwindel","Nach dem Sturz: blasse, kaltschweißige Haut, Tachykardie, Amnesie; ggf. Begleitsymptome durch den Sturz","Differenzialdiagnosen: Krampfanfall, Schock","Maßnahmen: Vitalfunktionen sichern, Basismonitoring, BZ; Lagerung nach Bewusstseinszustand – wach: Beine hoch, sonst stabile Seitenlage; Notarzt bei Bewusstlosigkeit oder instabilem Kreislauf"],
 r:{d:"N", s:"Synkope (Ohnmacht)", p:"S. 28"}},
{t:"Neurologische Notfälle", q:"Definieren Sie den Schlaganfall und nennen Sie seine drei Ursachen mit ihrer Häufigkeit. Lassen sie sich präklinisch unterscheiden?",
 a:["Schlaganfall (Apoplex, Hirninfarkt, Stroke, zerebraler Insult) = schlagartig beginnende neurologische Ausfälle als Folge einer Minderversorgung von Hirnzellen","Ischämischer Insult (80 %): eine hirnversorgende Arterie wird durch ein Blutgerinnsel verschlossen, die arterielle Versorgung ist unterbrochen","Hämorrhagischer Insult (15 %): eine arterielle Blutung schädigt die Hirnzellen","Sinus- und Hirnvenenthrombose (5 %): ein Gerinnsel verlegt eine abführende Vene, das Blut staut sich ins Gehirn zurück und schränkt die arterielle Durchblutung ein","Präklinisch nicht zu unterscheiden – dafür ist ein CCT erforderlich"],
 r:{d:"N", s:"Schlaganfall – Ursachen", p:"S. 28"}},
{t:"Neurologische Notfälle", q:"Nennen Sie die Symptome eines Schlaganfalls und beschreiben Sie Ihre Maßnahmen. Was bedeutet „Time is brain“?",
 a:["Beginn plötzlich, Zunahme innerhalb von Minuten","Halbseitige Lähmungen oder Sensibilitätsstörungen, Sprachstörungen, Sehstörungen, Bewusstseinsstörungen, Krampfanfälle","„Time is brain“ und „Golden Hour“ → schnelles Erkennen","xABCDE und SAMPLER mit Fokus auf D: Sprach- und Sprechvermögen, Pupillenreaktion, Sensibilität und Motorik (pDMS, Kreuzgriff, Arm-Vorhalte-Versuch), BEFAST","Wichtig: Symptombeginn und Medikamente","Oberkörperhochlagerung, 12-Kanal-EKG, Wärmeerhalt, Sauerstoffgabe","Vitalfunktionen stabilisieren und zügiger Transport in eine Klinik mit Stroke Unit; Notarzt bei vitaler Bedrohung"],
 r:{d:"N", s:"Schlaganfall – Symptome, Maßnahmen", p:"S. 29"}},
{t:"Neurologische Notfälle", q:"Was ist eine Hirnischämie? Nennen Sie Ursachen und grenzen Sie die transitorische ischämische Attacke (TIA) vom Hirninfarkt ab.",
 a:["Akute Durchblutungsstörung (Ischämie) mit Sauerstoffmangel der Nervenzellen; sterben die Hirnzellen ab, kommt es zum Hirninfarkt","Häufigste Ursache eines Schlaganfalls","Ursachen z.B.: fortgeschrittene Arteriosklerose, embolischer Infarkt (Blutgerinnsel verlegt ein hirnversorgendes Gefäß), lokaler Arterienverschluss (hirnversorgende Arterie wird kritisch eingeengt)","Symptome eines Schlaganfalls mit akut aufgetretenen neurologischen Ausfällen; vaskuläre Demenz (Einschränkung der kognitiven Leistungsfähigkeit)","TIA als Warnhinweis: vollständige Rückbildung","Hirninfarkt: keine oder unvollständige Rückbildung","Versorgung wie beim Schlaganfall – „Time is brain“"],
 r:{d:"N", s:"Hirnischämie und Hirninfarkt", p:"S. 31"}},
{t:"Neurologische Notfälle", q:"Vergleichen Sie intrazerebrale Blutung (ICB) und Subarachnoidalblutung (SAB) nach Lage, Ursache und Symptomen.",
 a:["Hirnblutung allgemein: Blutung innerhalb des knöchernen Schädels durch Zerreißung von Gefäßen","ICB: Riss einer hirnversorgenden Arterie mit Einblutung direkt in das Hirngewebe; Ursachen: Arteriosklerose und arterielle Hypertonie","ICB-Symptome: neurologische Ausfälle mit Zunahme über Minuten bis Stunden, vegetative Symptome, Bewusstseinsstörungen, Krampfanfälle","SAB: akute arterielle Einblutung in den äußeren Liquorraum zwischen Arachnoidea und Pia mater; Ursache: körperliche Anstrengung","SAB-Symptome: plötzlicher Vernichtungskopfschmerz über den gesamten Kopf mit Ausstrahlung in Nacken und Rücken, Angst, Übelkeit und Erbrechen, Meningismus, neurologische Ausfälle, Krampfanfälle, Sprachstörungen, zunehmende Bewusstseinsstörungen"],
 r:{d:"N", s:"Hirnblutungen – ICB, SAB", p:"S. 31"}},
{t:"Neurologische Notfälle", q:"Was ist Meningismus? Nennen Sie Ursachen, Differenzialdiagnosen und die Fragen, die Sie in der Anamnese stellen.",
 a:["Meningismus = Nackensteifigkeit","Ursachen: Meningitis, Subarachnoidalblutung, Sonnenstich","Differenzialdiagnosen: Bandscheibenvorfall, Verletzung der Wirbelsäule","(Hohes) Fieber?","Haben die Beschwerden schlagartig (SAB) oder allmählich (Meningitis) begonnen?","Neurologische Ausfälle oder Bewusstseinstrübung?","War der Patient starker Sonneneinstrahlung ausgesetzt?"],
 r:{d:"N", s:"Meningismus", p:"S. 29"}},
{t:"Neurologische Notfälle", q:"Unterscheiden Sie Meningitis und Enzephalitis. Nennen Sie Erreger, Übertragungsweg, Symptome und die wichtigste Maßnahme.",
 a:["Meningitis = Hirnhautentzündung, Enzephalitis = Hirnentzündung","Erreger: Viren (FSME- oder Herpesviren) oder Bakterien (Meningokokken, Pneumokokken); Übertragung per Tröpfcheninfektion","Bakterielle Meningitis: reduzierter Allgemeinzustand, starke Kopf- und Nackenschmerzen, hohes Fieber mit Verwirrtheit und Benommenheit, zunehmende Bewusstseinsstörungen, Meningismus (Schonhaltung mit überstrecktem Kopf und angewinkelten Beinen), Übelkeit, Erbrechen, Lichtscheu, auch Krampfanfälle","Virale Meningitis: weniger ausgeprägte Symptome, ähnelt einem grippalen Infekt","Enzephalitis: Fieber, Schüttelfrost, Kopfschmerzen, Sprachstörungen, sensible oder motorische Ausfälle, Verwirrtheit, Krampfanfälle, Bewusstseinsstörungen","Maßnahme: Infektionstransport, Eigenschutz!"],
 r:{d:"N", s:"Meningitis und Enzephalitis", p:"S. 32"}},
{t:"Neurologische Notfälle", q:"Unterscheiden Sie primäre und sekundäre Kopfschmerzen, beschreiben Sie Migräne, Spannungs- und Cluster-Kopfschmerz und nennen Sie Ihre Anamnesefragen.",
 a:["Migräne: sehr stark, pochend-pulsierend, halbseitig, mit Übelkeit und Erbrechen, Überempfindlichkeit gegen Licht und Geräusche, 4–72 Stunden, Zunahme bei körperlicher Belastung, ggf. vorher neurologische Ausfälle","Spannungskopfschmerz: leicht bis mittelstark, dumpf, drückend, Abnahme bei Entspannung oder Ablenkung, keine neurologischen Ausfälle","Cluster-Kopfschmerz: sehr stark im Bereich eines Auges, streng einseitig, vegetative Begleitsymptome wie Rötung, Tränenfluss oder Schwitzen, Attacken meist nachts, 12–180 Minuten","Sekundäre Kopfschmerzen als Folge organischer Erkrankungen: Hirntumor, Meningitis, SAB, Glaukomanfall, chronisches Subduralhämatom, hypertensive Entgleisung, Sonnenstich; auch Störungen von Zähnen, Nasennebenhöhlen, Kiefer und Hals-/Nackenmuskulatur, Allgemeininfektionen oder Impfungen","Anamnese: Schmerzcharakter und -stärke? Lokalisation (ein- oder beidseitig)? Weitere Symptome? Vorerkrankungen, Kopfverletzung? Was hat der Patient vor Beginn gemacht?"],
 r:{d:"N", s:"Kopfschmerzen", p:"S. 29–30"}},
{t:"Neurologische Notfälle", q:"Nennen Sie Ursachen und Zeichen eines erhöhten Hirndrucks sowie die Einklemmungszeichen. Welche Maßnahmen ergreifen Sie?",
 a:["Ursachen z.B.: Hirnblutungen, SHT, Meningitis, akutes Nierenversagen, Hitzschlag, Sonnenstich, fortgeschrittener Hirntumor","Hirndruckzeichen: frühmorgendliches schwallartiges Nüchternerbrechen, Übelkeit, Appetitlosigkeit, Kopfschmerzen, Schwindel, Sehstörungen (insb. Doppelbilder), Anstieg der Körpertemperatur, erweiterte lichtstarre Pupille auf der geschädigten Seite; psychische Veränderungen und Bewusstseinsstörungen","Einklemmungszeichen bei stark erhöhtem Hirndruck: Cushing-Triade (systolischer Blutdruckanstieg, Bradykardie, Atemstörungen bis -stillstand), schwallartiges Erbrechen, mittelweite oder weite entrundete lichtstarre Pupillen, Schielen, Ausfall der Reflexe, Koma, Versagen von Atmung und Kreislauf","Maßnahmen: xABCDE und Basismonitoring, SAMPLER; Oberkörperhochlagerung außer bei Bewusstlosigkeit; zügige Sauerstoffgabe, Wärmeerhalt; Notarzt und engmaschige Verlaufsbeobachtung, Intubation bei GCS < 9"],
 r:{d:"N", s:"Hirndruck- und Einklemmungszeichen", p:"S. 30"}},

/* ===== Anatomie & Physiologie ===== */
{t:"Anatomie & Physiologie", q:"Nennen Sie das Blutvolumen pro kg Körpergewicht bei Frauen, Männern, Kleinkindern und Neugeborenen sowie die Bestandteile des Blutplasmas.",
 a:["Blut = 6–8 % des Körpergewichts, ca. 5–6 l","Frauen ca. 60 ml/kg, Männer ca. 70 ml/kg, Kleinkinder ca. 85 ml/kg, Neugeborene ca. 90 ml/kg","Plasma (55 %): 90 % Wasser, 8 % Plasmaproteine (Albumin, Globuline), 2 % Elektrolyte/Hormone/Nährstoffe","Zellen (45 %): Erythrozyten, Leukozyten, Thrombozyten"],
 r:{d:"K", s:"Blut und Blutgefäße – Volumen, Bestandteile", p:"S. 1"}},
{t:"Anatomie & Physiologie", q:"Welche Aufgaben haben Erythrozyten, Leukozyten und Thrombozyten? Nennen Sie die Hämoglobin-Normwerte.",
 a:["Erythrozyten: Atemgastransport über Hämoglobin, gebildet im Knochenmark; O2-reiches Blut hellrot, O2-armes dunkelrot","Hb-Werte: Männer ca. 13–18 g/dl, Frauen 11,7–16 g/dl","Leukozyten: Immunabwehr (inkl. B- und T-Lymphozyten)","Thrombozyten: Blutstillung"],
 r:{d:"K", s:"Blut – Erythrozyten, Leukozyten, Thrombozyten", p:"S. 2"}},
{t:"Anatomie & Physiologie", q:"Was versteht man unter Anämie und welche Symptome treten auf?",
 a:["Nicht ein geringes Blutvolumen, sondern zu niedrige Blutbestandteile wie Hämoglobin","Symptome: erhöhte Herzfrequenz, blasse Haut und Schleimhäute, Müdigkeit, reduzierte Leistungsfähigkeit, Kopfschmerzen, Schwindel, Ohrensausen"],
 r:{d:"K", s:"Blut – Anämie", p:"S. 2"}},
{t:"Anatomie & Physiologie", q:"Erklären Sie das AB0-System: Wovon hängt die Blutgruppe ab, warum darf nicht beliebig transfundiert werden und welche Blutgruppe darf Erythrozytenkonzentrate von wem empfangen?",
 a:["Blutgruppe hängt von den Antigenen auf der Erythrozytenoberfläche ab (A, B, AB, 0)","Gegen fehlende Antigene bilden sich in den ersten Lebenswochen Antikörper (A → Anti-B, B → Anti-A, 0 → Anti-A und Anti-B, AB → keine)","Treffen Antigene auf passende Antikörper, verklumpt das Blut","EK-Empfang laut Tabelle: A von A und 0; B von B und 0; AB von A, B, AB und 0; 0 nur von 0","FFP-Empfang: A von A und AB; B von B und AB; AB nur von AB; 0 von A, B, AB und 0","Häufigkeit in Europa: A 44 %, 0 42 %, B 10 %, AB 4 %","Rhesus: Antigen D vorhanden = Rh-positiv, fehlt = Rh-negativ"],
 r:{d:"K", s:"Blut – Blutgruppe (Tabelle)", p:"S. 2"}},
{t:"Anatomie & Physiologie", q:"Beschreiben Sie den Ablauf der Hämostase und erklären Sie die Begriffe Thrombose und Embolie.",
 a:["Blutstillung: innerhalb von ca. 3 Minuten bildet sich ein Thrombozytenpfropf, der die Gefäßverletzung vorübergehend verschließt","Blutgerinnung: Pfropf wird durch einen stabilen Fibrinthrombus ersetzt, in den sich Blutzellen einlagern, bis die Gefäßwand geheilt ist","Thrombose: Gerinnung an falscher Stelle → Verstopfung eines Gefäßes","Embolie: Gerinnsel wird vom Blutfluss mitgerissen und verschließt ein entferntes Gefäß"],
 r:{d:"K", s:"Blut – Blutgerinnung (Hämostase)", p:"S. 2"}},
{t:"Anatomie & Physiologie", q:"Unterscheiden Sie Arterien, Venen und Kapillaren und erklären Sie die Windkesselfunktion sowie den Begriff Aneurysma.",
 a:["Arterien: leiten Blut vom Herzen weg (O2-reich im Körperkreislauf, O2-arm im Lungenkreislauf)","Venen: sammeln Blut aus den Kapillaren zurück zum Herzen (O2-arm im Körperkreislauf, O2-reich im Lungenkreislauf)","Kapillaren: feinstes Gefäßnetz zum Stoffaustausch im Gewebe","Windkesselfunktion: Arterien (v.a. Aorta) wandeln den pulsierenden Blutstrom in einen gleichmäßigen Volumenstrom um","Aneurysma: krankhafte, umschriebene Erweiterung einer Arterie mit Gefahr der Ruptur und lebensbedrohlicher Blutung"],
 r:{d:"K", s:"Blutgefäße", p:"S. 3"}},
{t:"Anatomie & Physiologie", q:"Beschreiben Sie den Weg des Blutes durch das Herz und nennen Sie dabei alle vier Herzklappen.",
 a:["Venöses Blut → obere/untere Hohlvene → rechter Vorhof → Trikuspidalklappe → rechter Ventrikel","→ Pulmonalklappe → Truncus pulmonalis (Lungenarterie) → Lunge (Gasaustausch)","→ Lungenvenen → linker Vorhof → Bikuspidal-/Mitralklappe → linker Ventrikel","→ Aortenklappe → Aorta → Körperkreislauf → zurück zum rechten Vorhof","Trikuspidal- und Mitralklappe = AV-Klappen (zwischen Vorhof und Kammer); Pulmonal- und Aortenklappe = Taschenklappen"],
 r:{d:"K", s:"Herz-Kreislauf-System – Blutstrom", p:"S. 4"}},
{t:"Anatomie & Physiologie", q:"Aus welchen drei Schichten besteht die Herzwand und wie wird das Herz selbst mit Blut versorgt?",
 a:["Endokard (Herzinnenhaut), Myokard (Herzmuskelschicht), Epikard (Herzaußenwand); außen der Herzbeutel (Perikard)","Versorgung über die Koronararterien (kranzförmig angeordnete linke und rechte Herzkranzgefäße) und Herzvenen – nicht durch das Blut im Innenraum","Rechte und linke Hälfte mit je Vorhof (Atrium) und Kammer (Ventrikel), getrennt durch das Septum"],
 r:{d:"K", s:"Herz – Aufbau", p:"S. 4"}},
{t:"Anatomie & Physiologie", q:"Beschreiben Sie die vier Phasen des Herzzyklus (Systole und Diastole).",
 a:["Systole (Kontraktion): Anspannungsphase – Kammern gefüllt, alle Klappen geschlossen, Druck steigt","Austreibungsphase – Kammerdruck übersteigt den Druck in Aorta und Truncus pulmonalis, die Taschenklappen öffnen sich, Blut strömt in die Gefäße, die Vorhöfe füllen sich","Diastole (Erschlaffung): Entspannungsphase – Kammerdruck sinkt, alle Klappen geschlossen","Füllungsphase – AV-Klappen öffnen sich, Blut fließt aus den Vorhöfen in die Kammern","Herztöne sind die Schallwellen der Herzmechanik (Auskultation); Herzgeräusche weisen auf Klappenveränderungen hin"],
 r:{d:"K", s:"Herz – Mechanik", p:"S. 4–5"}},
{t:"Anatomie & Physiologie", q:"Beschreiben Sie das Erregungsbildungs- und -leitungssystem des Herzens in der richtigen Reihenfolge.",
 a:["Sinusknoten (Taktgeber) → über die Vorhofmuskulatur","→ AV-Knoten (zwischen rechtem Vorhof und Kammer)","→ His-Bündel → Kammerschenkel (Tawara-Schenkel)","→ Purkinje-Fasern → Kammermuskulatur","Das vegetative Nervensystem lässt das Herz unwillkürlich und selbständig arbeiten"],
 r:{d:"K", s:"Herz – Elektrische Impulse", p:"S. 5"}},
{t:"Anatomie & Physiologie", q:"Definieren Sie Schlagvolumen und Herzzeitvolumen mit Normwerten und nennen Sie die Normwerte der Herzfrequenz bei Erwachsenen und Säuglingen.",
 a:["Schlagvolumen (SV): Blutmenge, die pro Herzzyklus von jeder Kammer ausgeworfen wird, ca. 70 ml","Herzzeitvolumen (HZV): Blutmenge pro Minute, ca. 5 l/min; HZV = HF × SV","Herzfrequenz: Sinusrhythmus 60–80/min bei Erwachsenen, Säuglinge 120–150/min","Bradykardie < 60, Tachykardie > 80, Arrhythmie = unregelmäßig","Puls = Druckwelle in den Arterien durch den Auswurf in der Systole, entspricht i.d.R. der HF"],
 r:{d:"K", s:"Herz – Herzfrequenz/Puls", p:"S. 5"}},
{t:"Anatomie & Physiologie", q:"Was ist der Blutdruck, wovon hängt er ab und welche Normwerte kennen Sie?",
 a:["Kraft, die das Blut auf die Gefäßwand ausübt","Einflussgrößen: Herzzeitvolumen, Gesamtblutvolumen, Gefäßwiderstand der Arterien","Normwert Erwachsene ca. 120/80 mmHg (systolisch/diastolisch)","Hochdrucksystem (Arterien des Körperkreislaufs, linke Kammer in der Systole) ca. 100 mmHg, ca. 15 % der Blutmenge; Niederdrucksystem (Venen, Kapillaren, Lungenkreislauf, rechtes Herz) < 20 mmHg"],
 r:{d:"K", s:"Herz – Blutdruck RR / Blutgefäße", p:"S. 3 und 5"}},
{t:"Anatomie & Physiologie", q:"Erklären Sie die Begriffe äußere und innere Atmung sowie Ventilation, Perfusion und Diffusion mit je einem Beispiel für eine Störung.",
 a:["Äußere Atmung (Lungenatmung): Gasaustausch in der Lunge – O2 diffundiert ins Blut (bindet an Hämoglobin), CO2 wird in die Alveolen abgegeben","Innere Atmung (Zellatmung): biochemischer Prozess in den Mitochondrien, Glucose wird mit O2 zu Wasser und CO2 abgebaut","Ventilation = Belüftung; Störung z.B. Bronchienverengung beim Asthmaanfall","Perfusion = Durchblutung; Störung z.B. Lungenembolie","Diffusion = Gasaustausch; Störung z.B. Lungenödem"],
 r:{d:"K", s:"Atmung – Grundlagen", p:"S. 6"}},
{t:"Anatomie & Physiologie", q:"Gliedern Sie die Atemwege in obere und untere Atemwege und nennen Sie die Aufgaben von Nase, Rachen und Kehlkopf.",
 a:["Obere Atemwege: Nasenhöhle und Rachen; untere Atemwege: Kehlkopf, Luftröhre, Bronchien bis Alveolen","Nase: nimmt Atemluft auf, erwärmt, reinigt, befeuchtet","Rachen (Pharynx): gemeinsamer Weg für Luft und Nahrung","Kehlkopf (Larynx): leitet Luft in die Luftröhre und Nahrung in die Speiseröhre; Stimmbildung","Trachea/Bronchien: Transport, Erwärmung, Befeuchtung, Reinigung; Lunge: Gasaustausch, Regulation des Säure-Basen-Haushalts; rechts 3, links 2 Lungenlappen"],
 r:{d:"K", s:"Atmung – Atmungsorgane", p:"S. 6"}},
{t:"Anatomie & Physiologie", q:"Beschreiben Sie den Aufbau der Pleura und erklären Sie, was bei Pleuraerguss und Pneumothorax passiert.",
 a:["Pleura = dünne Haut, bildet zwei getrennte Brustfellhöhlen für die Lungenflügel","Zwei Blätter: inneres Blatt (Lungenfell) und äußeres Blatt (Rippenfell), dazwischen Pleuraspalt mit Unterdruck und Flüssigkeit","Pleuraerguss: starke Zunahme der Flüssigkeit im Pleuraspalt","Pneumothorax: Luft dringt in den Pleuraspalt → Unterdruck aufgehoben → Lunge kollabiert"],
 r:{d:"K", s:"Atmung – Brustfell (Pleura)", p:"S. 6"}},
{t:"Anatomie & Physiologie", q:"Erklären Sie die Atemmechanik von Ein- und Ausatmung. Welche Muskeln sind beteiligt?",
 a:["Einatmung (aktiv): Zwerchfell kontrahiert und tritt tiefer → Brustraum erweitert sich → über den Unterdruck im Pleuraspalt folgt die Lunge → Unterdruck in der Lunge → Luft strömt ein (Bauchatmung)","Brustatmung: äußere Zwischenrippenmuskeln unterstützen für vertiefte Atmung; inspiratorische Atemhilfsmuskulatur an Hals, Brust, Rücken","Ausatmung (passiv): Rückstellkräfte lassen die Lunge sich zusammenziehen, Luft strömt aus","Exspiratorische Atemhilfsmuskulatur: innere Zwischenrippenmuskeln und Bauchmuskulatur","Zwerchfell = wichtigster Atemmuskel, trennt Brust- und Bauchhöhle"],
 r:{d:"K", s:"Atmung – Atemmechanik", p:"S. 6–7"}},
{t:"Anatomie & Physiologie", q:"Wie wird die Atmung reguliert, welche Atemanreize gibt es und wie hoch ist die normale Atemfrequenz beim Erwachsenen?",
 a:["Atemzentrum im Hirnstamm gibt Rhythmus und Frequenz nach pO2, pCO2 und pH vor","Informationen über Chemorezeptoren in Aorta, Halsschlagader und verlängertem Mark","Stärkster Atemanreiz: erhöhter pCO2; außerdem sinkender pH und niedriger pO2","Weitere Stimulation: Fieber, geringe Hypothermie, Schmerz, Adrenalin, Blutdruckabfall, Emotionen (Angst, Schreck, Freude)","Atemfrequenz Erwachsene i.d.R. 12–15/min"],
 r:{d:"K", s:"Atmung – Atmungsregulation, Atemanreize", p:"S. 7"}},
{t:"Anatomie & Physiologie", q:"Nennen Sie die Abschnitte des Verdauungskanals in der richtigen Reihenfolge sowie die drei Engstellen der Speiseröhre. Wo bleiben verschluckte Fremdkörper meist hängen?",
 a:["Mundhöhle → Rachen → Speiseröhre → Magen → Dünndarm (Zwölffinger-, Leer-, Krummdarm) → Dickdarm (Blinddarm mit Wurmfortsatz, Grimmdarm, Mastdarm) → Analkanal","Ösophagus ca. 25 cm mit 3 Engstellen: Ösophagusmund, Aortenenge, Zwerchfellenge; unterer Schließmuskel","Fremdkörper bleiben meist in der Aortenenge hängen","Sodbrennen: geschwächter Schließmuskel → Magensäure fließt zurück"],
 r:{d:"K", s:"Verdauung", p:"S. 7–8"}},
{t:"Anatomie & Physiologie", q:"Welche Aufgaben haben Leber und Bauchspeicheldrüse? Welche Hormone bildet das Pankreas und wie wirken sie?",
 a:["Leber (rechter Oberbauch unter dem Zwerchfell, 4 Lappen): wichtigstes Stoffwechselorgan – Kohlenhydrat-/Protein-/Fettstoffwechsel, Gallebildung, Entgiftung und Ausscheidung, Bildung der Blutproteine, Nährstoffspeicher","Gallenblase: Eindickung und Speicherung der Galle","Pankreas (hinter dem Magen, quer im Oberbauch): exokrin Verdauungssaft, endokrin Hormone","Insulin senkt den Blutzucker, Glukagon hebt ihn an"],
 r:{d:"K", s:"Verdauung – Verdauungsdrüsen", p:"S. 8"}},
{t:"Anatomie & Physiologie", q:"Beschreiben Sie den Aufbau des Harnsystems. Warum bekommen Frauen häufiger Blasenentzündungen und wie entsteht eine Nierenkolik?",
 a:["Nieren (Harnproduktion, Regulation Wasser-/Elektrolyt-/Säure-Basen-Haushalt, Hormonbildung) → Nierenbecken → Harnleiter (Ureter) → Harnblase → Harnröhre (Urethra)","Harnröhre bei Frauen ca. 5 cm, bei Männern ca. 20 cm → Bakterien gelangen bei Frauen leichter in die Blase","Nierenkolik: Harnsteine aus dem Nierenbecken bleiben in einer der 3 Engstellen des Harnleiters stecken","Nebennieren liegen auf den Nieren, sind aber nicht Teil des Harnsystems (bilden (Nor-)Adrenalin)"],
 r:{d:"K", s:"Harnsystem", p:"S. 8"}},
{t:"Anatomie & Physiologie", q:"Nennen Sie die sicheren Frakturzeichen und Ihre Maßnahmen bei einer Fraktur.",
 a:["Sichere Zeichen: abnorme Beweglichkeit, Fehlstellung, Krepitation (Knochenreiben), offene Fraktur","Fraktur = Kontinuitätsunterbrechung eines Knochens; komplett/inkomplett, offen/geschlossen","Maßnahmen: xABCDE, Monitoring, STU/Bodycheck, Schockprophylaxe, Ruhigstellung (achsengerecht bzw. in Schonhaltung), DMS-Kontrolle, bei offener Fraktur steril abdecken (Infektionsgefahr)"],
 r:{d:"K", s:"Bewegungssystem – Knochen/Fraktur", p:"S. 9"}},
{t:"Anatomie & Physiologie", q:"Wie ist die Wirbelsäule aufgebaut und woraus besteht der Brustkorb?",
 a:["Wirbelsäule: 7 Hals-, 12 Brust-, 5 Lendenwirbel, Kreuzbein (5 verschmolzene Wirbel), Steißbein (3–4 Wirbel); Wirbelkanal enthält das Rückenmark","C1 (Atlas) und C2 (Axis) besonders aufgebaut → Kopfdrehen und Nicken","Thorax: 12 Rippenpaare, Brustbein (Sternum), 12 Brustwirbel; Rippen 11 und 12 = falsche Rippen; schützt die Brustorgane"],
 r:{d:"K", s:"Bewegungssystem – Menschliches Skelett", p:"S. 9"}},
{t:"Anatomie & Physiologie", q:"Unterscheiden Sie Distorsion und Luxation und nennen Sie die PECH-Regel.",
 a:["Distorsion (Verstauchung): kurzzeitige Überdehnung; schmerzhafte Schwellung, Bewegungseinschränkung, Einblutung; sichere Diagnose nur per Röntgen","PECH: Pause, Eis, Compression, Hochlagern","Luxation (Ausrenkung): vollständige oder teilweise Verschiebung der gelenkbildenden Knochen; sicheres Zeichen z.B. leere Gelenkpfanne; xABCDE, Monitoring, DMS-Kontrolle"],
 r:{d:"K", s:"Bewegungssystem – Distorsion, Luxation", p:"S. 10"}},
{t:"Anatomie & Physiologie", q:"Wie wird das Nervensystem morphologisch und funktionell eingeteilt?",
 a:["Morphologisch: zentrales NS (Gehirn und Rückenmark) und peripheres NS (alle Nervenstrukturen außerhalb; 12 Hirnnervenpaare, 32 Spinalnervenpaare)","Funktionell: somatisches NS (willkürliche und reflexartige Bewegungen der Skelettmuskulatur) und vegetatives NS (unwillkürliche Steuerung innerer Organe; Sympathikus/Parasympathikus)","Gehirn: Großhirn (2 Hemisphären, 4 Lappen), Zwischenhirn, Hirnstamm (Mittelhirn, Brücke, verlängertes Mark), Kleinhirn; Versorgung über A. carotis und A. vertebralis"],
 r:{d:"K", s:"Nervensystem – Einteilung", p:"S. 10"}},
{t:"Anatomie & Physiologie", q:"Nennen Sie die Hirnhäute von außen nach innen. Was ist Liquor und welchen praktischen Nutzen hat sein Zuckergehalt im Rettungsdienst?",
 a:["Dura mater (harte Hirnhaut, 2 Schichten) → Subduralraum → Arachnoidea (Spinngewebshaut) → Subarachnoidalraum (Gefäße, Liquor) → Pia mater (weiche Hirnhaut, mit Gehirn verwachsen)","Liquor: im Subarachnoidalraum, den Ventrikeln und im Zentralkanal; transportiert Stoffwechselprodukte ab und schützt das ZNS wie ein Wasserkissen","Liquor ist zuckerhaltig → bei SHT den Blutzucker im Ausfluss aus Ohr/Nase/Mund testen, um Liquoraustritt zu erkennen"],
 r:{d:"K", s:"Nervensystem – Hirnhäute, Liquor", p:"S. 10–11"}},

/* ===== Pharmakologie ===== */
{t:"Pharmakologie", q:"Nennen Sie die 8-R-Regel im Umgang mit Medikamenten.",
 a:["Richtiger Patient","Richtiges Medikament","Richtige Dosierung","Richtige Verdünnung","Richtige Applikation","Richtiger Zeitpunkt","Richtige Lagerung","Richtige Dokumentation","zusätzlich: 4-Augen-Prinzip"],
 r:{d:"K", s:"Pharmakologie – Regeln für den Umgang", p:"S. 11"}},
{t:"Pharmakologie", q:"Welche Applikationswege kennen Sie? Wann und wo wird ein intraossärer Zugang angelegt?",
 a:["Enteral: oral, rektal, sublingual, bukkal","Parenteral: intravenös, intramuskulär, intraossär, subkutan, intranasal, inhalativ, transdermal","Intraossär: Zugang in den Knochenmarkraum per Nadel oder Bohrsystem, wenn kein peripherer Venenzugang möglich ist","Punktionsort meist proximale Tibia, medial 2–3 Querfinger unterhalb der Kniescheibenunterkante"],
 r:{d:"K", s:"Pharmakologie – Applikationsformen, Intraossär", p:"S. 11–12"}},
{t:"Pharmakologie", q:"Erklären Sie die Begriffe Pharmakokinetik, Pharmakodynamik, Kumulation und paradoxe Wirkung.",
 a:["Pharmakokinetik: Was macht der Körper mit der Arznei? (Aufnahme, Verteilung, Metabolisierung, Ausscheidung)","Pharmakodynamik: Was macht der Arzneistoff mit dem Körper?","Kumulation: Ansammlung eines Wirkstoffs im Körper","Paradoxe Wirkung: Gegenteil der erwarteten Wirkung","Metabolisierung: Verstoffwechselung in der Leber"],
 r:{d:"K", s:"Pharmakologie – Begriffe", p:"S. 11–12"}},
{t:"Pharmakologie", q:"Warum müssen Medikamente bei alten Patienten besonders vorsichtig eingesetzt werden?",
 a:["Alterungsprozesse verändern Kinetik und Dynamik","Abnahme von Durchblutung und Aktivität der Magen-Darm-Schleimhaut → orale Wirkung dauert länger","Abnahme von Muskel- und Wasseranteil, Zunahme von Fett → veränderte Verteilungsräume","Abnahme der Leber- und Nierenleistung → verlangsamte Metabolisierung und Elimination"],
 r:{d:"K", s:"Pharmakologie – Besondere Patientengruppen", p:"S. 11"}},
{t:"Pharmakologie", q:"Nennen Sie die vier Schmerzarten mit je einem Beispiel.",
 a:["Somatisch: Schädigung von Haut oder Bewegungsapparat","Viszeral: Störung innerer Organe","Neurogen: direkte Schädigung von Nervenstrukturen","Psychogen: ohne nachweisbare organische Ursache"],
 r:{d:"K", s:"Pharmakologie – Schmerztherapie", p:"S. 12"}},
{t:"Pharmakologie", q:"Nennen Sie je zwei Beispiele für Nicht-Opioid-Analgetika, Opioide und Benzodiazepine. Welche Gefahr besteht bei Opioiden und welche Antidote kennen Sie?",
 a:["Nicht-Opioide: Paracetamol (analgetisch, entzündungshemmend, fiebersenkend), Metamizol (bei Kolikschmerzen)","Opioide: Morphin, Piritramid, Fentanyl (Narkose); stärkste Analgetika, wirken über Opioidrezeptoren im Gehirn","Gefahr Opioide: Atemdepression → Antidot Naloxon","Benzodiazepine (Antikonvulsiva/Sedativa): Midazolam (Dormicum), Lorazepam (Tavor), Clonazepam (Rivotril), Diazepam (Valium) → Antidot Flumazenil"],
 r:{d:"K", s:"Pharmakologie – Schmerztherapie, Benzodiazepine", p:"S. 12"}},
{t:"Pharmakologie", q:"Adrenalin: Nennen Sie Indikationen mit jeweiligem Applikationsweg, unerwünschte Wirkungen und die Wirkdauer.",
 a:["Katecholamin zur Steigerung des Sympathikus-Effekts","Indikationen: Herz-Kreislauf-Stillstand/kardiogener Schock (i.v.), Anaphylaxie (i.m.), Obstruktion der oberen Atemwege (inhalativ)","UAW: Tachykardie, Extrasystolen, Kammerflimmern","Wirkt sofort, Wirkdauer 3–5 Minuten","Noradrenalin (Arterenol): bei Schock/schwerer Hypotonie, Wirkdauer 1–2 min"],
 r:{d:"K", s:"Pharmakologie – Katecholamine", p:"S. 13"}},
{t:"Pharmakologie", q:"Unterscheiden Sie Antikoagulanzien, Thrombozytenaggregationshemmer und Fibrinolytika mit je einem Beispiel.",
 a:["Antikoagulanzien: hemmen die plasmatische Gerinnung; z.B. Heparin bei AKS, Lungenembolie, Thrombose","Thrombozytenaggregationshemmer: verhindern das Verklumpen der Blutplättchen; z.B. ASS (wirkt nach 30 min, ca. 1 Woche)","Fibrinolytika/Thrombolytika: lösen frische Gerinnsel auf (Lysetherapie beim Herzinfarkt); bei Reanimation dann 60 min fortsetzen zur Verteilung","Gegenspieler: Antifibrinolytika (stabilisieren Thromben), Hämostyptika (Blutstillung bei kritischen äußeren Blutungen)"],
 r:{d:"K", s:"Pharmakologie – Gerinnung", p:"S. 13"}},
{t:"Pharmakologie", q:"Nennen Sie drei Antidote mit jeweiliger Indikation.",
 a:["Naloxon – Opioidvergiftung","Flumazenil – Benzodiazepin-Überdosierung","Atropin – Alkylphosphatvergiftung (Insektizide, chemische Kampfstoffe); auch bei Bradykardie/Herz-Kreislauf-Stillstand","Aktivkohle – orale Vergiftungen (Bindung des Giftstoffs)"],
 r:{d:"K", s:"Pharmakologie – Antidote", p:"S. 13"}},
{t:"Pharmakologie", q:"Welches Medikament wird bei Asthma/COPD zur Bronchienerweiterung eingesetzt und welche Medikamentengruppen bei einer anaphylaktischen Reaktion?",
 a:["Bronchospasmolytika, z.B. Salbutamol → Erschlaffung der Bronchialmuskulatur, Erweiterung der Atemwege","Anaphylaxie: Adrenalin (i.m.), Glukokortikoide, Antihistaminika","Weitere: medizinischer Sauerstoff bei Hypoxie; Antiemetika (Vomex, Zofran) gegen Übelkeit"],
 r:{d:"K", s:"Pharmakologie – Atmung", p:"S. 13"}},

/* ===== Infektionen & Hygiene ===== */
{t:"Infektionen & Hygiene", q:"Nennen Sie die Übertragungswege von Infektionen und erklären Sie die Begriffe nosokomial und iatrogen.",
 a:["Direkt oder indirekt (über kontaminierte Gegenstände = Schmierinfektion)","Enteral (über den Verdauungstrakt)","Parenteral: urogenital, intrauterin, perkutan (Haut), permukös (Schleimhaut), aerogen-inhalativ (Atemwege)","Nosokomial = im Krankenhaus erworben; iatrogen = durch medizinischen Eingriff verursacht","Endogen (eigene Darm-/Hautflora) vs. exogen (von außen)"],
 r:{d:"K", s:"Infektionen – Übertragungswege", p:"S. 13"}},
{t:"Infektionen & Hygiene", q:"Worin unterscheiden sich Bakterien und Viren in Aufbau, Beispielerkrankungen und Therapie?",
 a:["Bakterien: einzellige Lebewesen ohne Zellkern; Einteilung nach Färbbarkeit (gram+/–), Form (Kugel, Stäbchen, Spirale), O2-Bedarf (aerob/anaerob); z.B. Pneumonie, Meningitis, Harnwegsinfekt, Sepsis; Therapie: Antibiotika","Viren: keine eigenständigen Lebewesen, brauchen Wirtszellen, bestehen aus DNA/RNA + Hülle; z.B. grippale Infekte, Influenza, COVID, HIV, Hepatitis, Masern; Therapie meist symptomatisch","Weitere Erreger: Pilze (Antimykotika), Parasiten, Prionen (z.B. Creutzfeldt-Jakob)"],
 r:{d:"K", s:"Infektionen – Krankheitserreger", p:"S. 14"}},
{t:"Infektionen & Hygiene", q:"Erklären Sie Expositions- und Dispositionsprophylaxe mit Beispielen.",
 a:["Expositionsprophylaxe: Kontakt mit Erregern reduzieren – Händehygiene, Desinfektion, Lebensmittel-/Trinkwasserhygiene, Sexualhygiene, Insektenschutz, Isolierung infektiöser Personen, Meiden von Risikogebieten","Dispositionsprophylaxe: individuelle Empfänglichkeit senken – gesunder Lebensstil, Impfungen"],
 r:{d:"K", s:"Infektionsprophylaxe", p:"S. 14"}},
{t:"Infektionen & Hygiene", q:"Welche Schutzausrüstung tragen Sie bei Verdacht auf Norovirus, Tuberkulose und bakterielle Meningitis? Nennen Sie je ein Leitsymptom.",
 a:["Norovirus: aggressiver Brechdurchfall (3–5 Tage), Inkubation 12–48 h, aerogen/direkt/indirekt → volle Schutzausrüstung mit FFP3, Patient Maske ohne Ventil","Tuberkulose: Luftnot, blutiger Auswurf, aerogen → volle Schutzausrüstung mit FFP3","Meningitis: Meningismus, Kopfschmerz, Übelkeit, Lichtempfindlichkeit, Ausschlag bei Kindern; Tröpfcheninfektion → volle Schutzausrüstung mit FFP3; Therapie Antibiotika","Hepatitis: Fieber, Abgeschlagenheit → volle Schutzausrüstung mit OP-Maske"],
 r:{d:"K", s:"Organspezifische Infektionen", p:"S. 14"}},
{t:"Infektionen & Hygiene", q:"Beschreiben Sie den Ablauf eines Infektionstransports.",
 a:["Ankunft (Status 4): Schutzausrüstung anlegen und bereitlegen","Versorgung: Trennung Rein (am Patienten) und Unrein (Zuarbeit)","Fahrt: Fahrer legt Schutzkleidung ab, Fenster zur Fahrerkabine schließen, Außenlüftung, Anmeldung bei der Leitstelle als Infektionspatient","Ankunft Klinik: Schutzkleidung anlegen, Übergabe, Schutzkleidung ablegen","Status 6 zur Desinfektion, kontaminiertes Material sammeln und Müll kennzeichnen"],
 r:{d:"K", s:"Ablauf Infektionstransport", p:"S. 14–15"}},
{t:"Infektionen & Hygiene", q:"Wie gehen Sie bei einer Nadelstichverletzung vor? Welche Erreger sind relevant?",
 a:["Relevante Erreger: Hepatitis B und C, HIV","Nadel mit Desinfektionstupfer entfernen, Stelle gründlich desinfizieren","Blutfluss durch Druck ca. 1 Minute fördern, anschließend erneut desinfizieren","sterile Wundauflage, Meldung und Dokumentation","Schleimhautkontamination: ausgiebig mit Wasser spülen, schleimhautverträgliches Desinfektionsmittel, Meldung und Dokumentation"],
 r:{d:"K", s:"Vorgehen bei Kontamination", p:"S. 15"}},
{t:"Infektionen & Hygiene", q:"Nennen Sie die Leitsymptome von Infektionskrankheiten und erklären Sie den Begriff multiresistente Erreger.",
 a:["Krankheitsgefühl, schlechter AZ, Fieber und Schüttelfrost, Kopf- und Gliederschmerzen, Übelkeit, Erbrechen, Durchfall, Husten, Schnupfen, Schwitzen, Unruhe","MRE (z.B. MRSA, VRE, MRGN, ESBL): Antibiotika nicht wirksam; je nach Lokalisation des Erregers ggf. keine besonderen Maßnahmen nötig (z.B. Harntrakt)"],
 r:{d:"K", s:"Multiresistente Erreger / Leitsymptome", p:"S. 14"}},

/* ===== Untersuchung & Einsatzablauf ===== */
{t:"Untersuchung & Einsatzablauf", q:"Erklären Sie das 4S-Schema bei Ankunft an der Einsatzstelle.",
 a:["Scene: offensichtliche Gefahren (Strom, Verkehr, Einsturz, Wasser), Anzahl Patienten, weitere Betroffene → Einsatzstelle sichern, Eigenschutz","Safety: Gefahrenbeurteilung für Einsatzkräfte, Patienten, Dritte; spezielle Schutzmaßnahmen?","Situation: Was ist passiert, Anzahl Betroffene, Verletzungen, Schweregrad → Kategorisierung und Priorisierung","Support: weitere Einsatzkräfte/-mittel, besondere Geräte? → Nachforderung (Notarzt, RTW, Feuerwehr, Polizei, Schwerlast)"],
 r:{d:"U", s:"4S/SSSS", p:"S. 1"}},
{t:"Untersuchung & Einsatzablauf", q:"Nennen Sie die Bedeutung jedes Buchstabens im xABCDE-Schema mit je einer Untersuchung und einer Maßnahme.",
 a:["X – Extreme Bleeding: kritische Blutung? → manuelle Kompression, Druckverband, Tourniquet, Beckenschlinge","A – Airways: Atemwege frei/verlegt? → Ansprechen, Sichtkontrolle Mund/Rachen, Kopf überstrecken, Fremdkörper entfernen, Stiffneck bei Trauma, stabile Seitenlage/Tubus","B – Breathing: Atmung vorhanden/ausreichend? → sehen, hören, fühlen; Auskultation; SpO2; Hautfarbe; Halsvenen/Hautemphysem → O2, ggf. Beatmung","C – Circulation: Hautfarbe/-temperatur, Recap-Zeit, Puls, EKG, RR, Temperatur, Blutungen → Blutung stoppen, Schocklagerung","D – Disability: Orientierung, BZ, Pupillen, BEFAST, GCS → Monitoring, ggf. Intubationsbereitschaft","E – Exposure/Environment: entkleiden, Bodycheck, Wärmeerhalt, SAMPLER, Frakturen immobilisieren, Wundversorgung"],
 r:{d:"U", s:"xABCDE-Tabelle", p:"S. 1–3"}},
{t:"Untersuchung & Einsatzablauf", q:"Welche Maßnahmen stehen bei „X“ zur Verfügung und warum steht X vor A?",
 a:["Manuelle Kompression, Druckverband, Tourniquet, Beckenschlinge, Immobilisation (insb. Hals)","Eine kritische Blutung führt innerhalb kürzester Zeit zum hypovolämischen Schock und Tod → muss vor allem anderen gestoppt werden","Bei Trauma zusätzlich Schnelle Trauma-Untersuchung (STU)"],
 r:{d:"U", s:"xABCDE – X Extreme Bleeding", p:"S. 1"}},
{t:"Untersuchung & Einsatzablauf", q:"Was prüfen Sie bei „B – Breathing“ und wie führen Sie die Atemkontrolle durch?",
 a:["Atmung vorhanden? Atembewegungen? Ausreichend? Atemgeräusche? Atemarbeit? SpO2? Zyanose? Hinweise auf Lungenembolie/Hautemphysem?","Atemkontrolle: sehen, hören, fühlen; Auskultation (Frequenz, Tiefe, Geräusche wie Brodeln/Pfeifen, asynchrone Atembewegung)","Pulsoximeter an Finger/Ohrläppchen (Kinder ggf. Klebesensor, z.B. Augenbraue), Sensor sauber halten","Hals/Nacken: gestaute Halsvenen, „Knisterpapier“ (Hautemphysem)","→ Sauerstoffgabe, ggf. Intubation und kontrollierte Beatmung; beruhigen"],
 r:{d:"U", s:"xABCDE – B Breathing", p:"S. 1–2"}},
{t:"Untersuchung & Einsatzablauf", q:"Wie bestimmen Sie die Rekapillarisierungszeit und was sagt sie aus? Welche weiteren Untersuchungen gehören zu „C“?",
 a:["Fingernagel oder Handballen drücken → Zeit bis zur Wiederdurchblutung ≤ 2 Sekunden normal; verlängert = Zentralisation/Schock","Weitere C-Untersuchungen: Hautfarbe/-temperatur, Pulskontrolle (Tachykardie > 80, Bradykardie < 60), EKG, Blutdruck, Körpertemperatur, Blutungen/Frakturen, STU","Maßnahmen: Blutung stoppen, bei Schock Beine hoch"],
 r:{d:"U", s:"xABCDE – C Circulation", p:"S. 2"}},
{t:"Untersuchung & Einsatzablauf", q:"Was wird unter „D – Disability“ untersucht? Nennen Sie die groben Stufen der Bewusstseinsbeurteilung mit zugehöriger Konsequenz.",
 a:["Orientierung zu Raum/Zeit, Blutzucker (< 140, nüchtern < 100), Pupillenkontrolle, Lähmungen, Bewusstseinsstörungen, Stoffwechselentgleisung, Drogen/Alkohol, BEFAST bei V.a. Schlaganfall","Glasgow-Coma-Scale grob: wach; ansprechbar → Monitoring; reagiert nur auf Schmerz → Intubationsbereitschaft; bewusstlos → Schutzintubation"],
 r:{d:"U", s:"xABCDE – D Disability", p:"S. 2–3"}},
{t:"Untersuchung & Einsatzablauf", q:"Nennen Sie sechs Indikationen für die Nachforderung eines Notarztes.",
 a:["Bewusstlosigkeit","kritische Blutung","Reanimation","MANV","Entbindung","Verdacht auf Herzinfarkt","Polytrauma","Suizid(versuch)"],
 r:{d:"U", s:"Notarztindikation", p:"S. 3"}},
{t:"Untersuchung & Einsatzablauf", q:"Beschreiben Sie den Ablauf der Schnellen Trauma-Untersuchung (STU).",
 a:["Einer fixiert den Kopf, tastet Nacken und Schädeldecke bis zu den Schläfen ab, Handschuhe auf Blut prüfen","Zweiter: seitlich am Rippenübergang drücken, unterhalb des Sternums auf den Brustkorb drücken, Bauch tasten (hart?), Becken seitlich komprimieren","Oberschenkel nacheinander auf Frakturen prüfen (eine Hand am Knie, andere innen/außen unterhalb der Leiste)","Patient auf die Seite drehen (Kopfführer sagt an; Zweiter greift oberhalb Knie und Hüfte, Führer über Kreuz an Hüfte und Schulter), Wirbelsäule abtasten, zurückdrehen"],
 r:{d:"U", s:"Schnelle-Trauma-Untersuchung", p:"S. 3"}},
{t:"Untersuchung & Einsatzablauf", q:"Beschreiben Sie das Vorgehen im Einsatz vom Eintreffen bis zum „10 for 10“.",
 a:["1. Vorstellung und Umgebungsscan nach 4S","2. Erste Checks: X kritische Blutung, A Sichtkontrolle Atemwege, B Atemkontrolle (sehen, fühlen, hören) + Hautfarbe, C Recap-Zeit, Puls, ggf. STU","3. „10 for 10“: kurze Teambesprechung, Einordnung in unkritisch / potenziell kritisch / kritisch, ggf. Nachforderung von Einsatzmitteln oder -kräften","4. Alle weiteren, umfassenderen Checks aus A–E"],
 r:{d:"U", s:"Vorgehen im Einsatz", p:"S. 3"}},
{t:"Untersuchung & Einsatzablauf", q:"Erläutern Sie das SAMPLER-Schema mit den jeweiligen Fragen.",
 a:["S – Symptoms: aktuelle Symptome/Schmerzen, akut oder chronisch, seit wann, Verlauf, Arztbesuch? (ggf. OPQRST)","A – Allergies: bekannte Allergien/Unverträglichkeiten (Medikamente, Nahrungsmittel)","M – Medication: welche Medikamente, regelmäßig/aktuell, Dosierung, Medikamentenplan","P – Past Medical History: Vorerkrankungen, Eingriffe, Behandlungen, Hausarzt","L – Last: letzte Mahlzeit, zuletzt getrunken, letzter Toilettengang, Auffälligkeiten","E – Events: was ist vorausgegangen?","R – Risk Factors; (S – Schwangerschaft)"],
 r:{d:"U", s:"SAMPLER", p:"S. 4"}},
{t:"Untersuchung & Einsatzablauf", q:"Erläutern Sie das BEFAST-Schema und die Konsequenz bei positivem Befund.",
 a:["B – Balance: Gleichgewicht gestört? Patient aufstehen und 1–2 Schritte gehen lassen","E – Eyes: Pupillenreaktion (Hand über die Nase, seitlich einleuchten, andere Pupille beobachten), Sehstörungen","F – Face: Gesichtsasymmetrie/hängender Mundwinkel","A – Arms: Armhalteversuch, einseitige Schwäche","S – Speech: Sprachstörung","T – Time: Symptombeginn erfragen und dokumentieren; schnelle Reaktion und Transport in eine Stroke Unit (Ziel nach Rücksprache mit der Leitstelle)"],
 r:{d:"U", s:"(BE)FAST", p:"S. 5"}},

/* ===== Neu ergänzt: Respiratorische Notfälle ===== */
{t:"Respiratorische Notfälle", q:"Ein Patient hustet. Welche Fragen stellen Sie zur Anamnese und welche Rückschlüsse ziehen Sie aus Dauer und Auswurf?",
 a:["Akut aufgetreten oder seit mehreren Wochen? Akut: akute Bronchitis, Pneumonie (mit Fieber und schwerem Krankheitsgefühl), Lungenembolie (mit Luftnot), Fremdkörperaspiration, Reizstoffinhalation","Chronisch: COPD, Asthma, Bronchialkarzinom","Ist der Husten produktiv (Auswurf/Sputum)? Eitrig: Bronchitis, Pneumonie – rötlich und schaumig: fortgeschrittenes Lungenödem","Blut im Auswurf oder größere Blutmengen ausgehustet? Bronchialkarzinom, Tuberkulose, Bronchitis, Pneumonie","Vorerkrankungen (Asthma, COPD)? Medikamente? Husten ist eine bekannte Nebenwirkung von ACE-Hemmern"],
 r:{d:"N", s:"Husten, Bluthusten – Anamnese", p:"S. 2"}},
{t:"Respiratorische Notfälle", q:"Worauf achten Sie beim ersten Eindruck (Begrüßung und Inspektion) eines Patienten mit Atemproblemen?",
 a:["Klagt der Patient über schlechte oder keine Luft?","Wie spricht der Patient – ganze Sätze, Wortgruppen oder gar nicht?","Besteht die Atemnot bereits in Ruhe?","Wird die Atemhilfsmuskulatur eingesetzt?","Atemnebengeräusche beim Auskultieren?","Husten – mit oder ohne Auswurf?","Hautkolorit, zyanotisch?","Umfeld? Rauchgeruch?","Anschließend SAMPLER und Untersuchung nach xABCDE"],
 r:{d:"N", s:"Anamnese und Untersuchung – Erster Eindruck", p:"S. 2–3"}},
{t:"Respiratorische Notfälle", q:"Welche Komplikationen kann eine Pneumonie nach sich ziehen?",
 a:["Atemabhängige Schmerzen und Pleuraerguss durch Reizung der Pleura","Risiko für venöse Thrombosen oder eine Lungenembolie durch die Bettruhe","Septischer Schock, wenn der Erreger über die Blutbahn streut","Respiratorische Insuffizienz oder akutes Lungenversagen mit Lungenödem"],
 r:{d:"N", s:"Lungenentzündung (Pneumonie) – Komplikationen", p:"S. 5"}},
{t:"Respiratorische Notfälle", q:"Definieren Sie Aspiration und Bolusgeschehen und nennen Sie die Symptomatik.",
 a:["Aspiration = versehentliche Einatmung von Fremdkörpern oder Flüssigkeit","Maximalform Bolusgeschehen: der Fremdkörper verlegt die oberen Atemwege teilweise oder komplett","Symptome: plötzlich beginnende Hustenattacke, ggf. mit Würgen und/oder Atemnot","Unruhe bis Todesangst","Stridor, Zyanose","zunehmende Hypoxie bis Bewusstlosigkeit und hypoxisches Kreislaufversagen"],
 r:{d:"N", s:"Aspiration – Definition, Symptomatik", p:"S. 8"}},
{t:"Respiratorische Notfälle", q:"Nennen Sie die Symptome einer CO2-Erstickung und Ihre Maßnahmen. Warum ist die Einsatzstelle hier besonders gefährlich?",
 a:["Symptome: vertiefte Atmung, Tachykardie","Kopfschmerz, Schwindel, Unruhe","ggf. Krampfanfälle","Zyanose und Bewusstlosigkeit bis Atem- und Kreislaufstillstand","Gefahr: CO2 ist schwerer als Luft, sammelt sich am Boden und verdrängt den Sauerstoff – also auch für die Einsatzkräfte lebensgefährlich (Silos, Jauchegruben, Biogasanlagen, Weinkeller)","Maßnahmen: Spezialkräfte nachfordern, Eigenschutz beachten, Vitalfunktionen nach xABCDE + Basismonitoring, O2-Gabe 10–15 l/min, Notarzt nachfordern"],
 r:{d:"N", s:"Kohlendioxid-Erstickung", p:"S. 9"}},
{t:"Respiratorische Notfälle", q:"Definieren Sie das Lungenödem und erklären Sie, warum daraus eine Hypoxämie entsteht. Welche Formen gibt es außer dem kardialen und dem toxischen Lungenödem?",
 a:["Lungenödem = Flüssigkeitsansammlung im Gewebe zwischen den Lungenbläschen (Interstitium) und/oder in den Lungenbläschen (Alveolen)","Flüssigkeit tritt aus den Lungenkapillaren in das Interstitium aus oder gelangt in die Alveolen, wenn das Gewebe sie nicht mehr aufnehmen kann","Folge: eingeschränkte Dehnbarkeit der Lunge und verlängerte Diffusionsstrecke für die Atemgase → Hypoxämie","Weitere Formen: Höhenlungenödem, allergisches bzw. entzündliches Lungenödem, Lungenkontusion"],
 r:{d:"N", s:"Lungenödem – Definition, Arten", p:"S. 6–7"}},

/* ===== Neu ergänzt: Herz-Kreislauf & Schock ===== */
{t:"Herz-Kreislauf & Schock", q:"Was ist ein distributiver Schock? Nennen Sie die drei Unterformen mit je einer Ursache.",
 a:["Distributiver Schock (Verteilungsschock): Vasodilatation (Weitstellung der Gefäße) plus erhöhte Durchlässigkeit der Gefäße mit Flüssigkeitsverlust ins Gewebe → relativer Volumenmangel","Anaphylaktischer Schock: z.B. Insektenstiche, Nahrungsmittelallergene","Septischer Schock: durch schwere Infektionskrankheiten","Neurogener (spinaler) Schock: durch Schädel-Hirn-Trauma oder Wirbelsäulentrauma"],
 r:{d:"N", s:"Schock – Arten, Distributiver Schock", p:"S. 11"}},
{t:"Herz-Kreislauf & Schock", q:"Unterscheiden Sie den kardiogenen vom obstruktiven Schock mit je zwei Ursachen.",
 a:["Beide gehören zum kardialen Schock","Kardiogener Schock: verminderte Pumpleistung des Herzens führt zu relativem Volumenmangel – Ursachen z.B. Herzinfarkt, Herzinsuffizienz","Obstruktiver Schock: vermindertes Herzzeitvolumen durch mechanische Einengung des Herzens – Ursachen z.B. Herzbeuteltamponade, Spannungspneumothorax"],
 r:{d:"N", s:"Schock – Arten, Kardialer Schock", p:"S. 10–11"}},
{t:"Herz-Kreislauf & Schock", q:"Nennen Sie die Leitsymptome der Herz-Kreislauf-Notfälle und die Ursachen akuter Thoraxschmerzen. Welche Ursachen sprechen für atemabhängige, welche für atemunabhängige Schmerzen?",
 a:["Leitsymptome: wie bei respiratorischen Notfällen, akute Thoraxschmerzen, Dyspnoe und Zyanose, Halsvenenstauung, Herzrhythmusstörungen, Herzrasen/Tachykardie, Synkope, Wassereinlagerungen/Ödeme","Akute Thoraxschmerzen: plötzlich auftretende Brustschmerzen mit Ausstrahlung in Unterkiefer, Arm und Schulter als Ausdruck einer akut lebensbedrohlichen Situation; Todesangst","Ursachen: Gewebeschädigung oder O2-Unterversorgung des Myokards, z.B. ACS, hypertensiver Notfall, akutes Aortensyndrom, Lungenembolie, Pneumothorax, Thoraxtrauma","Atemabhängige Schmerzen: Lungenembolie, Pleuritis, Rippenfraktur","Atemunabhängige Schmerzen: ACS, Angina pectoris"],
 r:{d:"N", s:"Herz-Kreislauf-Notfälle – Leitsymptome, Akute Thoraxschmerzen", p:"S. 11–12"}},
{t:"Herz-Kreislauf & Schock", q:"Was ist mit dem umgangssprachlichen „psychischen Schock“ gemeint und warum ist der Begriff im Rettungsdienst irreführend?",
 a:["Umgangssprachlich gemeint ist eine akute Belastungsreaktion","Das ist kein Schock im medizinischen Sinn: es liegt kein Kreislaufversagen mit gestörter Mikrozirkulation vor","Der medizinische Schockbegriff beschreibt ein Kreislaufversagen, das unbehandelt zum Multiorganversagen führen kann","Die Zusammenfassung führt ihn deshalb nicht unter den Schockarten"],
 r:{d:"N", s:"Schock – „Psychischer Schock“", p:"S. 11"}},
{t:"Herz-Kreislauf & Schock", q:"Erklären Sie Hoch- und Niederdrucksystem des Kreislaufs mit den zugehörigen Gefäßabschnitten und Druckwerten.",
 a:["Hochdrucksystem: Arterien des Körperkreislaufs und die linke Kammer in der Systole","Blutdruck etwa 100 mmHg, enthält nur ca. 15 % der Gesamtblutmenge","Niederdrucksystem: Kapillaren und Venen des Körperkreislaufs, alle Gefäße des Lungenkreislaufs, rechtes Herz sowie linker Vorhof und linke Kammer in der Diastole","Blutdruck < 20 mmHg"],
 r:{d:"K", s:"Blutgefäße – Hoch-/Niederdrucksystem", p:"S. 3"}},
{t:"Herz-Kreislauf & Schock", q:"Ein Patient entwickelt nach einem Wespenstich Atemnot, Quaddeln und wird kreislaufinstabil. Welche Schockform liegt vor und welche Medikamentengruppen kommen zum Einsatz?",
 a:["Anaphylaktischer Schock – eine Form des distributiven Schocks","Pathomechanismus: Vasodilatation und erhöhte Gefäßdurchlässigkeit → relativer Volumenmangel","Adrenalin (bei Anaphylaxie i.m.) als wichtigstes Medikament – Katecholamin, steigert den Sympathikuseffekt, wirkt sofort für 3–5 Minuten","Zusätzlich Glukokortikoide und Antihistaminika"],
 r:{d:"K", s:"Pharmakologie – Atmung / Katecholamine", p:"S. 13"}},

/* ===== Neu ergänzt: Anatomie & Physiologie ===== */
{t:"Anatomie & Physiologie", q:"Beschreiben Sie den Aufbau einer Zelle und nennen Sie die vier Gewebearten mit je einer Aufgabe.",
 a:["Zelle = kleinste Einheit eines belebten Organismus","Aufbau: Zellmembran (Hülle), Zytoplasma mit Zellorganellen, Zellkern (enthält die Erbinformationen)","Blut- und Immunzellen können ihren Aufenthaltsort verändern, alle übrigen Zellen sind in Zellverbänden fixiert","Zellen + Interzellularsubstanz (Wasser, Fasern, Grundsubstanz) bilden das Gewebe","Epithelgewebe: bedeckt Oberflächen als (Schleim-)Haut, bildet Drüsen und Sekret, nimmt Reize auf","Binde-/Stütz-/Fettgewebe: Stütz- und Schutzfunktion, Energie- und Kalziumspeicher, Knorpel zur Druckverteilung","Nervengewebe: Neuronen und Gliazellen","Muskelgewebe: quergestreifte Skelettmuskulatur, quergestreifte Herzmuskulatur, glatte Muskulatur"],
 r:{d:"K", s:"Zellen und Gewebe", p:"S. 1"}},
{t:"Anatomie & Physiologie", q:"Erklären Sie Normovolämie, Hypovolämie und Hypervolämie mit je einer Ursache und nennen Sie die Funktionen des Blutes.",
 a:["Normovolämie: normales Blutvolumen","Hypovolämie: vermindertes Blutvolumen – Folge innerer oder äußerer Blutungen, großer Flüssigkeitsverlust bei Durchfall oder zu geringe Flüssigkeitsaufnahme","Hypervolämie: erhöhtes Blutvolumen – Ausdruck einer Hyperhydration, z.B. durch Infusion","Funktionen des Blutes: Transport von Atemgasen, Nährstoffen, Wärme, Hormonen, Stoffwechselprodukten und Elektrolyten","Blutstillung: Abdichtung der Gefäßwand und Stoppen des Blutverlusts","Erregerabwehr: einzelne Blutbestandteile sind Teil des Immunsystems"],
 r:{d:"K", s:"Blut und Blutgefäße – Volumen, Funktionen", p:"S. 1"}},
{t:"Anatomie & Physiologie", q:"Erklären Sie das Rhesus-Blutgruppensystem.",
 a:["Menschen mit dem Antigen D auf den Erythrozyten sind Rhesus-positiv","Fehlt das Antigen D, sind sie Rhesus-negativ","Wie beim AB0-System hängt die Blutgruppe von den Proteinen (Blutgruppenantigenen) an der Oberfläche der Erythrozyten ab","Bei einer Bluttransfusion dürfen Blutgruppenantigene keinesfalls auf die passenden Antikörper treffen – sonst verklumpt das Blut"],
 r:{d:"K", s:"Blut – Blutgruppe, Rhesussystem", p:"S. 2"}},
{t:"Anatomie & Physiologie", q:"Welche Funktion hat das Immunsystem und wie wird es eingeteilt?",
 a:["Funktion: erkennt und beseitigt Erreger, schädliche körperfremde Stoffe und veränderte Körperzellen (= Antigene)","Dabei erkennt und verschont es körpereigene Strukturen","Einteilung: angeborene (unspezifische) Abwehr","Erworbene (spezifische) Abwehr: ab dem Erstkontakt durch Infektion oder Impfung wird für jedes Antigen ein passendes Abwehrmittel produziert"],
 r:{d:"K", s:"Immunsystem", p:"S. 3"}},
{t:"Anatomie & Physiologie", q:"Beschreiben Sie das lymphatische System: primäre und sekundäre lymphatische Organe sowie den Aufbau des Lymphgefäßsystems.",
 a:["Primäre lymphatische Organe: Entstehung und Reifung der Immunzellen/Lymphozyten – Knochenmark und Thymus (kleines Organ hinter dem oberen Brustbein)","Sekundäre lymphatische Organe: dorthin wandern die Lymphozyten und treffen auf die passenden Antigene zur Immunreaktion – Lymphknoten, Milz (größtes lymphatisches Organ), MALT (Gewebe in den Schleimhäuten)","Lymphgefäßsystem: kein geschlossener Kreislauf","Beginnt mit Lymphkapillaren frei im Gewebe, die sich zu immer größeren Gefäßen vereinigen und in die Venen münden","Aufgabe: Transport von Flüssigkeit aus den Geweben in das Kreislaufsystem"],
 r:{d:"K", s:"Lymphatisches System", p:"S. 3"}},
{t:"Anatomie & Physiologie", q:"Aus welchen beiden Kreisläufen besteht das Kreislaufsystem und welche Aufgabe hat das Herz darin?",
 a:["Das Kreislaufsystem besteht aus zwei hintereinandergeschalteten Kreisläufen: Körperkreislauf und Lungenkreislauf","Das Herz pumpt O2-armes Blut zur Lunge (Lungenkreislauf) und O2-reiches Blut in den Körper (Körperkreislauf)","Herz-Kreislauf-System (kardiovaskuläres System) = Herz + Gefäße; versorgt die Zellen mit Sauerstoff und Nährstoffen","Im Lungenkreislauf führen die Arterien O2-armes, die Venen O2-reiches Blut – im Körperkreislauf umgekehrt"],
 r:{d:"K", s:"Herz-Kreislauf-System", p:"S. 3–4"}},
{t:"Anatomie & Physiologie", q:"Wodurch entstehen Herztöne und Herzgeräusche und wie werden sie untersucht?",
 a:["Herztöne = Schallwellen der Herzmechanik (Klappenschluss, Kontraktion)","Untersuchung durch Auskultation mit dem Stethoskop","Herzgeräusche können auf krankhafte Veränderungen der Herzklappen hinweisen","Die Auskultation gehört im xABCDE bei B und C zu den Basismaßnahmen"],
 r:{d:"K", s:"Herz – Mechanik, Herztöne", p:"S. 5"}},
{t:"Anatomie & Physiologie", q:"Beschreiben Sie Lage, Fassungsvermögen und Funktion des Magens. Woraus besteht der Magensaft?",
 a:["Sackförmiges Hohlorgan zwischen Speiseröhre und Dünndarm, im linken Oberbauch direkt unter dem Zwerchfell","Fassungsvermögen ca. 1,5 l","Funktion: Zerkleinerung der Nahrung durch Muskelbewegungen und Vermischung mit Magensäure","Der entstehende Speisebrei (Chymus) wird nach ca. 2 Stunden portionsweise an den Dünndarm weitergegeben","Magenschleimhaut mit Magendrüsen produziert täglich ca. 2 l Magensaft aus Salzsäure, Pepsinogen und Magenschleim"],
 r:{d:"K", s:"Verdauung – Magen", p:"S. 8"}},
{t:"Anatomie & Physiologie", q:"Welche Aufgaben haben Dünn- und Dickdarm? Nennen Sie jeweils Abschnitte, Länge und Verweildauer.",
 a:["Dünndarm: Zwölffingerdarm, Leerdarm, Krummdarm; Länge ca. 3–5 m","Aufgabe: Verdauung und Resorption der Nährstoffe, Weitertransport des Chymus zum Dickdarm; Einmündung über die Bauhin-Klappe","Dickdarm: Blinddarm mit Wurmfortsatz, Grimmdarm, Mastdarm; beginnt im rechten Unterbauch, Länge ca. 1,5 m","Aufgabe: Bildung von Stuhl durch Entzug von Wasser aus dem Speisebrei und bakterielle Zersetzung","Der Darminhalt bleibt ca. 1–3 Tage im Dickdarm bis zur Ausscheidung; danach Analkanal"],
 r:{d:"K", s:"Verdauung – Dünndarm, Dickdarm", p:"S. 8"}},
{t:"Anatomie & Physiologie", q:"Wo liegen die Nebennieren, gehören sie zum Harnsystem und was bilden sie?",
 a:["Die Nebennieren liegen oberhalb der Nieren","Sie gehören ausdrücklich NICHT zum Harnsystem – sie sind Hormondrüsen","Sie bilden Adrenalin und Noradrenalin (Katecholamine)","Diese steigern den Effekt des Sympathikus – im Rettungsdienst auch als Medikamente relevant"],
 r:{d:"K", s:"Harnsystem – Nebennieren", p:"S. 8"}},
{t:"Anatomie & Physiologie", q:"Welche Aufgaben haben Knochen, welche Knochenformen gibt es und wie ist ein Knochen aufgebaut? Erklären Sie proximal und distal.",
 a:["Aufgaben: Stabilisierung des Körpers, Schutz der Organe, Kalziumspeicher, Blutbildung im Knochenmark","Formen: Röhrenknochen (Epiphysen an den Enden, Diaphyse als Schaft mit Knochenmark, dazwischen Metaphysen), kurze Knochen, platte Knochen","Aufbau: Knochenhaut (Periost), äußere Schicht (Kompakta), innere Schicht (Spongiosa aus Knochenbälkchen)","Proximal = zum Rumpf hin gelegen, distal = vom Rumpf entfernt","Skelettsystem insgesamt: ca. 230 Knochen, Knorpel, Gelenke und Bänder"],
 r:{d:"K", s:"Bewegungssystem – Knochen", p:"S. 9"}},
{t:"Anatomie & Physiologie", q:"Unterscheiden Sie echte und unechte Gelenke und nennen Sie vier Gelenktypen mit Beispiel.",
 a:["Echte Gelenke: haben einen Gelenkspalt mit Gelenkflüssigkeit und sind von einer Gelenkkapsel umgeben","Unechte Gelenke: kein Gelenkspalt, verbunden durch Knorpel, Bindegewebe oder Verknöcherungen; Beweglichkeit gering (z.B. zwischen Brustbein und Rippen, Schädelknochen, Elle/Speiche, Schienbein/Wadenbein)","Kugelgelenk – Hüfte; Sattelgelenk – Daumengrundgelenk","Eigelenk – obere Handwurzel; Scharniergelenk – Ellenbogen","Radgelenk – unterer Kopf; planes Gelenk – Hand- und Fußwurzel"],
 r:{d:"K", s:"Bewegungssystem – Gelenke", p:"S. 9"}},
{t:"Anatomie & Physiologie", q:"Gliedern Sie das Gehirn und nennen Sie die arterielle Versorgung sowie die Aufgabe des Rückenmarks.",
 a:["Großhirn (2 Hemisphären, 4 Lappen)","Zwischenhirn (Hypothalamus, Hypophyse, Thalamus, Epiphyse)","Hirnstamm (Mittelhirn, Brücke, verlängertes Mark) – hier liegt u.a. das Atemzentrum","Kleinhirn","Arterielle Versorgung über A. carotis und A. vertebralis","Rückenmark: 32 Segmente zur Reizleitung zwischen Gehirn und peripherem Nervensystem sowie für Reflexe"],
 r:{d:"K", s:"Nervensystem – ZNS", p:"S. 10"}},
{t:"Anatomie & Physiologie", q:"Wie entsteht Sodbrennen und wo bleiben verschluckte Fremdkörper in der Speiseröhre meist hängen?",
 a:["Der untere Schließmuskel der Speiseröhre (Ösophagussphinkter) ist geschwächt","Magensäure fließt in die Speiseröhre zurück und löst ein Brennen hinter dem Brustbein aus","Speiseröhrenfremdkörper bleiben meist in der Aortenenge hängen","Die Speiseröhre ist ca. 25 cm lang und hat 3 Engstellen: Ösophagusmund, Aortenenge, Zwerchfellenge"],
 r:{d:"K", s:"Verdauung – Speiseröhre", p:"S. 7"}},
{t:"Anatomie & Physiologie", q:"Welche Atemhilfsmuskulatur unterscheidet man und wann wird sie eingesetzt?",
 a:["Inspiratorische Atemhilfsmuskulatur: Muskeln an Hals, Brust und Rücken","Exspiratorische Atemhilfsmuskulatur: innere Zwischenrippenmuskeln und Bauchmuskulatur","Normalerweise ist die Ausatmung passiv – durch die Rückstellkräfte zieht sich die Lunge zusammen","Der sichtbare Einsatz der Atemhilfsmuskulatur ist ein wichtiges Alarmzeichen bei Dyspnoe (z.B. Asthmaanfall, AECOPD)"],
 r:{d:"K", s:"Atmung – Atemmechanik", p:"S. 6–7"}},
{t:"Anatomie & Physiologie", q:"Beschreiben Sie den Aufbau des Schädels, des Beckens und der oberen sowie unteren Extremitäten.",
 a:["Schädel (Cranium): 17 Einzelknochen, gegliedert in Hirn- und Gesichtsschädel","Becken (Pelvis): enthält die Beckenorgane und verbindet Rumpf und Beine; besteht aus 2 Hüftbeinen (Beckengürtel), verbunden mit dem Kreuzbein – diese Verbindung ist der Beckenring","Obere Extremitäten: Schultergürtel (Schlüsselbein, Schulterblatt) und Arm (Oberarmknochen, Elle, Speiche, Hand); Gelenke: Schulter-, Ellenbogen-, Hand- und Fingergelenke","Untere Extremitäten: Beckengürtel und Beine (Oberschenkelknochen, Schienbein und Wadenbein, Fuß); Gelenke: Hüft-, Knie- (mit Kniescheibe als Sehne), Sprung- und Zehengelenke"],
 r:{d:"K", s:"Bewegungssystem – Menschliches Skelett", p:"S. 9"}},

/* ===== Neu ergänzt: Pharmakologie ===== */
{t:"Pharmakologie", q:"Erklären Sie die Begriffe Freiname, Handelsname, Applikation, Indikation/Kontraindikation, Wechselwirkung und Metabolisierung.",
 a:["Freiname: chemisch definierter Arzneistoff (Wirkstoffname)","Handelsname: Name für die Vermarktung, z.B. Aspirin","Applikation: Verabreichung des Medikaments","Indikation/Kontraindikation: Einsatzgebiete und Anwendungszwecke bzw. Gegenanzeigen","Wechselwirkung: hemmende oder verstärkende Wirkung bei mehreren Medikamenten","Metabolisierung: Verstoffwechselung in der Leber","Wirkmechanismus: Erklärungsmodell für das Zustandekommen der Wirkung","Rechtliche Grundlagen: Arzneimittelgesetz und Betäubungsmittelgesetz"],
 r:{d:"K", s:"Pharmakologie – Begriffe", p:"S. 11"}},
{t:"Pharmakologie", q:"Wie müssen Medikamente gekennzeichnet, aufbewahrt und gelagert werden?",
 a:["Kennzeichnung durch den Hersteller: Frei- und Handelsname, Charge und Verfallsdatum","Kennzeichnung durch den Vorbereitenden: Medikamentenname und Dosierung","Aufbewahrung und Lagerung nach Herstellerangaben und sicher vor Fremdzugriff","Nur in der Originalverpackung","Reste sind sachgerecht zu entsorgen","Zusätzlich gelten das 4-Augen-Prinzip und die 8-R-Regel"],
 r:{d:"K", s:"Pharmakologie – Regeln für den Umgang", p:"S. 11"}},
{t:"Pharmakologie", q:"Was ist eine Narkose, warum ist dabei eine Atemwegssicherung nötig und wie bereiten Sie sie vor? Nennen Sie das AMPEL(n)-Schema.",
 a:["Narkose = reversible Ausschaltung des Bewusstseins und der Schmerzempfindung sowie Dämpfung der vegetativen Reflexe durch Medikamente","Atemwegssicherung und Beatmung sind erforderlich, weil Schutzreflexe und Spontanatmung ausfallen","Vorbereitung: Fremdanamnese nach AMPEL(n) bzw. Eigenanamnese mit Aufklärung und Einverständnis","AMPEL(n): Allergien, Medikation, Persönliche Anamnese, Ereignis, Letzte Nahrungsaufnahme, Narkoseanamnese","Anlage von 2 i.v.-Zugängen, Material für Narkose, Intubation und Beatmung","Medikamente aufziehen und kennzeichnen, Absaugbereitschaft, Standardmonitoring"],
 r:{d:"K", s:"Pharmakologie – Narkose im RD", p:"S. 12"}},
{t:"Pharmakologie", q:"Welche Medikamentengruppen werden für eine Narkose im Rettungsdienst benötigt? Nennen Sie je ein Beispiel.",
 a:["Sauerstoff – zur Präoxygenierung und Beatmung","Opioid","Narkotikum – i.d.R. Propofol, Esketamin („Ketanest“), Thiopental oder Midazolam","Muskelrelaxans („Pantolax“)"],
 r:{d:"K", s:"Pharmakologie – Narkose im RD", p:"S. 12"}},
{t:"Pharmakologie", q:"Noradrenalin: Nennen Sie Indikation, unerwünschte Wirkungen und Wirkdauer. Worin unterscheidet es sich vom Adrenalin?",
 a:["Noradrenalin („Arterenol“) ist wie Adrenalin ein Katecholamin zur Effektsteigerung des Sympathikus","Indikation: schwere Hypertonie, Schock","Unerwünschte Wirkungen: Tachykardie, Herzrhythmusstörungen bis Kammerflimmern, zerebrale Blutungen, Lungenödem","Pharmakokinetik: wirkt sofort, Wirkdauer 1–2 Minuten (Adrenalin 3–5 Minuten)","Adrenalin ist Mittel der Wahl bei Herz-Kreislauf-Stillstand (i.v.) und Anaphylaxie (i.m.); als drittes Katecholamin wird Dopamin genannt"],
 r:{d:"K", s:"Pharmakologie – Katecholamine", p:"S. 13"}},
{t:"Pharmakologie", q:"Welche Medikamentengruppen werden bei hypertensiver Entgleisung, Angina pectoris und Herzrhythmusstörungen eingesetzt? Nennen Sie je ein Beispiel.",
 a:["Antihypertensiva (Blutdrucksenker) bei hypertensiver Entgleisung – Sympatholytikum Urapidil","Antianginosa bei Angina pectoris – Nitroglyzerin","Antiarrhythmika bei Herzrhythmusstörungen – z.B. der Beta-Blocker Metoprolol oder Atropin","Atropin wird auch als Antidot bei Alkylphosphatvergiftung und bei Herz-Kreislauf-Stillstand eingesetzt"],
 r:{d:"K", s:"Pharmakologie – Herz-Kreislauf-System", p:"S. 13"}},
{t:"Pharmakologie", q:"Wozu dienen Antifibrinolytika und Hämostyptika?",
 a:["Antifibrinolytika blockieren den Abbau von Thromben und stabilisieren so bereits gebildete Gerinnsel","Hämostyptika fördern die Verengung von Gefäßen und das Verkleben der Blutzellen in Wunden","Einsatz der Hämostyptika: Blutstillung bei kritischen äußeren Blutungen","Gegenspieler sind Fibrinolytika/Thrombolytika, die frische Gerinnsel auflösen (Lysetherapie beim Herzinfarkt)"],
 r:{d:"K", s:"Pharmakologie – Gerinnung", p:"S. 13"}},
{t:"Pharmakologie", q:"Bei welchen Patientengruppen ist im Umgang mit Medikamenten besondere Vorsicht geboten und wie unterscheidet sich die Applikation bei Kindern?",
 a:["Kinder: Applikation eher nasal, rektal oder inhalativ","Alte Menschen: veränderte Kinetik und Dynamik durch Alterungsprozesse","Untergewichtige und adipöse Patienten – veränderte Verteilungsräume","Patienten mit schweren Leber- und/oder Nierenerkrankungen – verlangsamte Metabolisierung und Elimination"],
 r:{d:"K", s:"Pharmakologie – Besondere Patientengruppen", p:"S. 11"}},

/* ===== Neu ergänzt: Infektionen & Hygiene ===== */
{t:"Infektionen & Hygiene", q:"Was ist der Unterschied zwischen einer endogenen und einer exogenen Infektion?",
 a:["Endogene Infektion: die Erreger stammen aus der eigenen Darm- oder Hautflora des Patienten","Exogene Infektion: die Erreger kommen von außerhalb","Davon zu unterscheiden sind die Übertragungswege (direkt/indirekt, enteral, parenteral) sowie nosokomiale (im Krankenhaus erworbene) und iatrogene (durch medizinischen Eingriff verursachte) Infektionen"],
 r:{d:"K", s:"Infektionen – Erregerherkunft", p:"S. 13"}},
{t:"Infektionen & Hygiene", q:"Welche Krankheitserreger gibt es außer Bakterien und Viren? Nennen Sie je ein Beispiel und die Therapie.",
 a:["Pilze: Infektionen bei Immunschwäche an Haut oder Schleimhäuten, z.B. Nagel- oder Vaginalpilz; Therapie: Antimykotika","Parasiten: einzellige Parasiten (Malariaerreger), Würmer (Bandwurm) und Gliederfüßer (Spinnen, Zecken, Mücken, Flöhe)","Prionen: pathologisch gefaltete Proteine, die im Gehirn degenerative Veränderungen auslösen können, z.B. Creutzfeldt-Jakob-Krankheit","Krankheitserreger allgemein = Mikroorganismen, die Infektionen oder Krankheiten auslösen"],
 r:{d:"K", s:"Infektionen – Krankheitserreger", p:"S. 14"}},
{t:"Infektionen & Hygiene", q:"Beschreiben Sie Hepatitis und HIV/AIDS hinsichtlich Krankheitsbild, Übertragung und Schutzausrüstung.",
 a:["Hepatitis: Entzündung des Lebergewebes mit Fieber und Abgeschlagenheit; Übertragung direkt (Hepatitis A auch indirekt)","Schutzausrüstung bei Hepatitis: volle Schutzausrüstung mit OP-Maske","AIDS/HIV: Immundefektsyndrom durch das HI-Virus, verschiedene Stadien; Übertragung direkt","Beide Erreger sind bei einer Nadelstichverletzung relevant (Hepatitis B und C, HIV)"],
 r:{d:"K", s:"Organspezifische Infektionen", p:"S. 14"}},
{t:"Infektionen & Hygiene", q:"Beschreiben Sie die bakterielle Meningitis: Symptomatik, Verlauf, Übertragung, Schutzausrüstung und Therapie.",
 a:["Meningitis = Hirnhautentzündung durch Viren, Pilze, Parasiten oder Bakterien – im Rettungsdienst ist die bakterielle Form relevant","Symptome: akutes Krankheitsgefühl, Meningismus (Nackensteifigkeit), Kopfschmerzen, Übelkeit, Lichtempfindlichkeit; bei Kindern zusätzlich Ausschlag","Verlauf: bei etwa einem Drittel mit Sepsis","Übertragung: Tröpfcheninfektion → volle Schutzausrüstung mit FFP3","Therapie: Antibiotika"],
 r:{d:"K", s:"Organspezifische Infektionen – Meningitis", p:"S. 14"}},

/* ===== Neu ergänzt: Untersuchung & Einsatzablauf ===== */
{t:"Untersuchung & Einsatzablauf", q:"Was prüfen Sie bei „A – Airways“ und welche Maßnahmen stehen Ihnen zur Verfügung?",
 a:["Geprüft wird: Sind die Atemwege frei oder verlegt? Liegt eine Schwellung vor?","Ansprechen des Patienten","Sichtkontrolle von Mund- und Rachenraum","ggf. Kopf überstrecken und Fremdkörper entfernen","Bei Trauma: Stiffneck (HWS-Immobilisation)","Atemwegssicherung durch stabile Seitenlage oder Tubus – mit Absaugbereitschaft"],
 r:{d:"U", s:"xABCDE – A Airways", p:"S. 1"}},
{t:"Untersuchung & Einsatzablauf", q:"Was wird bei „E – Exposure/Environment“ untersucht und welche Maßnahmen gehören dazu?",
 a:["Geprüft wird: Wärmeverlust, Verletzungen, Erkrankungen","Anamnese nach SAMPLER","Maßnahmen: Wärmeerhalt","Entkleiden und Untersuchen, Bodycheck","Frakturen immobilisieren","Wundversorgung"],
 r:{d:"U", s:"xABCDE – E Exposure/Environment", p:"S. 3"}},
{t:"Untersuchung & Einsatzablauf", q:"Beschreiben Sie das Vorgehen im Trauma-Einsatz und nennen Sie den Unterschied zum internistischen Einsatz.",
 a:["Vorstellung und Scan der Umgebung nach 4S","X – kritische Blutung stoppen","A – Sichtkontrolle der Atemwege","B – Atemkontrolle (sehen, fühlen, hören)","Beim Trauma wird die Schnelle-Trauma-Untersuchung (STU) früh durchgeführt; danach Hautfarbe, C – Recap-Zeit, Pulskontrolle, STU","„10 for 10“: kurze Besprechung mit dem Teamkollegen, Einordnung in unkritisch / potentiell kritisch / kritisch, ggf. Nachforderung von Einsatzmitteln oder -kräften","Anschließend alle weiteren und umfassenderen Checks aus A–E"],
 r:{d:"U", s:"Vorgehen im Trauma-Einsatz", p:"S. 3–4"}},
{t:"Untersuchung & Einsatzablauf", q:"Was ist das „10 for 10“ und wozu dient es?",
 a:["Kurze, bewusst eingeplante Besprechung mit dem Teamkollegen nach den ersten Checks","Einordnung des Patienten in unkritisch, potentiell kritisch oder kritisch","ggf. Nachforderung von Einsatzmitteln oder Einsatzkräften","Erst danach folgen alle weiteren und umfassenderen Checks aus A–E"],
 r:{d:"U", s:"Vorgehen im Einsatz – 10 for 10", p:"S. 3"}},
{t:"Untersuchung & Einsatzablauf", q:"Wo kann ein Pulsoximeter angebracht werden und worauf achten Sie? Welche Sichtkontrolle am Hals gehört zu „B“?",
 a:["Messorte: Finger, Ohrläppchen; bei Kindern ggf. als Klebesensor an der Augenbraue","Die Messstelle soll möglichst rein sein","Das Pulsoximeter wird nach der Messung am Patienten belassen (Monitoring)","Sichtkontrolle von Hals und Nacken auf gestaute Halsvenen (Hinweis auf Lungenembolie) oder „Knisterpapier“ unter der Haut (Hautemphysem)","Konsequenz: Sauerstoffgabe, ggf. Intubation und kontrollierte Beatmung"],
 r:{d:"U", s:"xABCDE – B Breathing", p:"S. 2"}},
];
